quests[82018] = { id = 82018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Itharius", description = "Are you familiar with the Temple of Atal'Hakkar? It has a storied history that I will not retell here, but it is currently under the stewardship of a host of mighty green dragons. The chief guardian of the temple is a great dragon named Eranikus, and he is known to be particularly attuned to the dream. It is my hope that he may be able to aid us. Go to the Swamp of Sorrows and meet with the ranger there known as Itharius. He may know how to reach out to Eranikus to petition his aid.", sourceObjective = "Seek out Itharius somewhere in the Swamp of Sorrows.", progress = "Greetings, {race}.", completion = "You come seeking Eranikus? Your coming may be ill-timed, {class}. I fear something is amiss at the Temple of Atal'Hakkar. Come, let us speak further.", sourceObjectiveStatus = "unverified-source-field" }
quests[82019] = { id = 82019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Under", description = "In its day the so-called Sunken Temple was home to a sect of trolls dedicated to the resurrection of their ancient blood deity, Hakkar the Soul-Flayer. Before the Atal'ai could realize their grim ambitions, Ysera's wrath smote the temple into the mire and she left the dragon Eranikus and his host as its guardians. Of late I have heard many whispers of trolls once again active there, and I fear what may have become of the dragons there.\n\nPlease, venture inside the temple and see what you can learn.", sourceObjective = "Find out more about what is happening in the Temple of Atal'Hakkar.", progress = "What news do you bring of Eranikus?", completion = "The scene you described is most harrowing. This is far worse than I feared. I can only hope that some of the dragons there yet live and can be rallied.", sourceObjectiveStatus = "unverified-source-field" }
quests[82020] = { id = 82020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Moonglade", description = "Return to Loganaar and inform him of what we've learned. I'm going to try and scout the temple myself to hopefully make contact with the dragons, or at least glean more information.", sourceObjective = "Return to Loganaar in Moonglade.", completion = "<Loganaar sighs heavily>\n\nMore bad news. Very well, I thank you for risking your life to enter the temple to learn what you did, and for bringing word back to me. I must inform the other druids so that we may determine what to do next. \n\nThank you for now. I may call upon you again in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[82021] = { id = 82021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fortuitous Turn of Events", description = "Well hello {name}! I was just standing here taking in the scenery and I just couldn't help but overhear your predicament. Fortuitously, I think I can provide just what you need to help you with your little \"evil devouring nightmare monster\" problem.", sourceObjective = "Listen to what the Shadowy Figure has to say.", progress = "I must say, this couldn't have worked out better if I had planned it. It seems that fate smiles upon you, friend.\n\n<You get the distinct impression that the shadowy figure before you is smirking>", completion = "Isn't it encouraging to have someone like me around that tends to have just what you need, just when you need it?", sourceObjectiveStatus = "unverified-source-field" }
quests[82022] = { id = 82022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bad News...", description = "So, the good news is that a solution exists. The bad news is that getting what you need to be able to survive the dread is going to require a bit of effort. I know, its unfortunate that it's so hard to get good help these days. If this adventurer had managed to do the one simple thing I asked them to do in the first place, you'd be tucking in a hot meal and a cold ale at an inn somewhere, none the wiser about any of this right now.", sourceObjective = "Find the adventurer that the Shadowy Figure described, and recover the Void-Powered Vambraces.", progress = "How goes the search?", completion = "Ah it seems that these are de-powered. Unfortunate, but easily remedied. To recharge these, you'll need to find a dense concentration of Naga spellcasters and massacre them en masse. Rarely, they may carry something called a \"Voidcore\", so sift through the bodies, bring me one and.... Hah! Joking! If you could see the look on your face... \n\nGive me one moment and I should be able to infuse these with some power.... and there we are! You are ready to slay a Nightmare.", sourceObjectiveStatus = "unverified-source-field" }
quests[82023] = { id = 82023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Vambraces", description = "You see, I'm a knight of some renown and I recently took it upon myself to rid the land of a particularly terrible evil making its home on a nearby island to the east. When I found the vile creature, a truly epic battle was met. We must have fought for hours until at last I sent the beast into full retreat, no doubt run off to succumb to its wounds. I was barely able to make it back to town myself before I collapsed in exhaustion. The vambraces must have slipped from my arm during the battle.", sourceObjective = "Find the lair of the \"Beast\" that the injured gnome was referring to and recover the Void-Powered Vambraces", progress = "<The young murloc looks at you and makes a cute gurgling sound.> \n\nYou notice there is a small pile of dirt next to the Murloc. Perhaps a burrow of some sort. Maybe you should check it for the vambraces?", completion = "You've found a small burrow belonging to an adorable and seemingly friendly young Murloc. Surely this isn't the beast that the gnome was referring to?\n\n<The tiny murloc makes a small gurgling noise and proceeds to burp up a pair of slime-covered vambraces at your feet>", sourceObjectiveStatus = "unverified-source-field" }
quests[82043] = { id = 82043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wild Gods", description = "Somethin' be wrong with de loa of Hyjal. De most powerful spirits of nature have been watchin' over the mountain for thousands of years, but dey be startin' to vanish, one by one.\n\nAgamaggan, de greatest of de ancient loa, died long ago. But de Amani trolls have ways to speak with de dead. Find de voodoo dey be usin', and take it to de Razorfen. Talk to Agamaggan and ask him what be happenin' to his kin.", sourceObjective = "Collect a Wildwhisper Draught from Jintha'alor in the Hinterlands, then use it at the top of Razorfen Downs to speak to the Spirit of Agamaggan.", completion = "Even beyond the veil of death, I have sensed a shadow falling across Hyjal and my kin.\n\nTake this, mortal. You will need it for what is to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[82044] = { id = 82044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wild Gods", description = "A darkness has taken root in the Emerald Dream, and it has shadowed the ancient spirits of Hyjal with confusion and fear.\n\nSeek out these delirious spirits, mortal, and use my roar to draw them into combat.\n\nWhen you slay their corrupted forms, their spirits will be cleansed and they will be reborn anew.", sourceObjective = "Deliver Wild Offerings to the Shadowtooth Emissary in Felwood. Use Agamaggan's Roar on a Delirious Ancient and defeat it to earn Wild Offerings.", progress = "I sense a change on de mountain, {name}. What you bringin' me?", completion = "You be doin' de loa a great service, {name}. I'll be usin' de offerings to guide dem back to Hyjal.\n\nBring me more offerings, and I may part wit' some of my clan's treasures.", sourceObjectiveStatus = "unverified-source-field" }
quests[82055] = { id = 82055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Dunes Deck", description = "Now that you have gathered all of the Dune cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few weeks, so you will have to wait until they are here next.", sourceObjective = "Return the Dunes Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of dunes!   Congratulations!", completion = "So you have put together a deck of Dunes.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[82056] = { id = 82056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Nightmares Deck", description = "Now that you have gathered all of the Nightmare cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few weeks, so you will have to wait until they are here next.", sourceObjective = "Return the Nightmares Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of nightmares!   Congratulations!", completion = "So you have put together a deck of Nightmares.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[82057] = { id = 82057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Plagues Deck", description = "Now that you have gathered all of the Plague cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few weeks, so you will have to wait until they are here next.", sourceObjective = "Return the Plagues Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of plagues!   Congratulations!", completion = "So you have put together a deck of Plagues.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[82058] = { id = 82058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Wilds Deck", description = "Now that you have gathered all of the Wild cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few weeks, so you will have to wait until they are here next.", sourceObjective = "Return the Wilds Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of wilds!   Congratulations!", completion = "So you have put together a deck of Wilds.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[82062] = { id = 82062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ever After", description = "Had to be sure we could trust you. These kind of friends are hard to come by. \n\nThere's a malignancy growing, a third faction within Azeroth. Both the Horde and Alliance are unwittingly working towards their own ends. Slowing their advances and forming information networks are all we have resources for.\n\nTake this, raise your spirits, and harken back to better days. There will be a time soon where we need our bolstered numbers for a show of force.", sourceObjective = "<You're handed a small parcel with a shirt neatly folded over it.>", sourceObjectiveStatus = "unverified-source-field" }
quests[82068] = { id = 82068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight the Nightmare Incursions", description = "Complete a Nightmare Incursion mission in Feralas or Hinterlands today and you'll earn an extra reward.", sourceObjective = "Complete a Nightmare Incursion mission in Feralas or Hinterlands and then report to Field Captain Korlian or Field Captain Arunnel.", progress = "Have you completed a mission yet?", completion = "Well done, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[82071] = { id = 82071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purifying Fire", description = "There is something the charred notes are wrapped around. Some sort of sapta. You don't remember it looking or smelling quite like this, but it otherwise appears the same. Something about it feels off, as if it's been tainted by some other magic. There must be a Spirit Rock nearby, though you don't remember there being any. Finding it might allow you to get to the bottom of this strangeness.", sourceObjective = "Find the tainted Spirit Rock and drink the Murky Fire Sapta.", completion = "You strong. You cleanse fire. You stop corruption.\n\n\nYou find and stop corruption.", sourceObjectiveStatus = "unverified-source-field" }
quests[82072] = { id = 82072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purging Earth", description = "A familiar bottle of sapta lay wrapped in the smudged notes. It's strangely murky, yet the magic mostly feels familiar. There is a faint sensation of foreign magic, tainting the mix. Your instincts tell you there must be a Spirit Rock nearby, though you cannot recall any. Locating it may help you get to the bottom of this mystery.", sourceObjective = "Find the tainted Spirit Rock and drink the Murky Earth Sapta.", completion = "Life grow again. Strength needed.\n\n\nCorruption elsewhere. Find and stop.", sourceObjectiveStatus = "unverified-source-field" }
quests[82073] = { id = 82073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Water", description = "Faded and soggy notes are wrapped around a murky bottle. Sapta. You can't recall it ever looking like this, but it seems similar enough. It smells odd, as if tainted somehow. A Spirit Rock must be nearby, though it would be long-abandoned. Finding it might be the missing piece to this strange puzzle.", sourceObjective = "Find the tainted Spirit Rock and drink the Murky Water Sapta.", completion = "You cleansed. You restored. Strong spirit. You help.\n\n\nCorruption still lives. Stop it.", sourceObjectiveStatus = "unverified-source-field" }
quests[82074] = { id = 82074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Answering Fire's Call", description = "You strong. Strong enough.\n\n<The elemental sparks and flickers.>\n\nElements of Feralas. Essence. Find Shrine.\n\nTake Fragment. Will help.", sourceObjective = "Collect 3 Elemental Essence from the water elementals on The Forgotten Coast across from Sardor Isle in Feralas and combine them with the Fragment of Fire to summon help at the corrupted shrine there.", progress = "Will purify shrine.", completion = "Need help. Other elements strong. Bring them.", sourceObjectiveStatus = "unverified-source-field" }
quests[82075] = { id = 82075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Answering Earth's Call", description = "Life grow now. Need more. Need stop corruption.\n\n<Rocks scrape against each other as the elemental shifts.>\n\nFeralas. Elements. Essence and Shrine.\n\nFind. Use Fragment and find. Help life grow.", sourceObjective = "Collect 3 Elemental Essence from the water elementals on The Forgotten Coast across from Sardor Isle in Feralas and combine them with the Fragment of Earth to summon help at the corrupted shrine there.", progress = "Life grow here now.", completion = "Life grow here now. Need more. Other elements. Help.", sourceObjectiveStatus = "unverified-source-field" }
quests[82076] = { id = 82076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Answering Water's Call", description = "Strong spirit. You help stop corruption.\n\n<Water rages as it swirls around the elemental.>\n\nBretheren. Elements of Feralas help. Essence will find Shrine.\n\nFragment help too. Cleanse corruption.", sourceObjective = "Collect 3 Elemental Essence from the water elementals on The Forgotten Coast across from Sardor Isle in Feralas and combine them with the Fragment of Water to summon help at the corrupted shrine there.", progress = "Will cleanse shrine.", completion = "Cleanse shrine now. Not strong enough. Need others. Other elements.", sourceObjectiveStatus = "unverified-source-field" }
quests[82081] = { id = 82081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Broken Ritual", description = "This prestine scapula is all too recognizable -- Hakkar was summoned into the physical world and defeated. The trolls on Yojamba Island will want to hear more about what happened inside of Sunken Temple.", sourceObjective = "Bring the Scapula of the Fallen Avatar to Molthor in Yojamba Isle.", progress = "{name}, what news do you have from the Temple of Atal'Hakkar?", completion = "It can't be... the rumors of the Temple of the Atal'Hakkar are true? \n\nYour victory inside of da Sunken Temple will be remembered by da Zandalari for a long time, mon. This bone.. it be an odd choice to deliver us.. but no doubt was one used to summon Hakkar into da physical world -- it will be in good hands now, {name}. We no longer have to worry about Hakkar coming back thanks to your efforts, mon... right?", sourceObjectiveStatus = "unverified-source-field" }
quests[82083] = { id = 82083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Broken Ritual", description = "This prestine scapula is all too recognizable -- Hakkar was summoned into the physical world and defeated. The trolls on Yojamba Island will want to hear more about what happened inside of Sunken Temple.", sourceObjective = "Bring the Scapula of the Fallen Avatar to Molthor in Yojamba Isle.", progress = "{name}, what news do you have from the Temple of Atal'Hakkar?", completion = "It can't be... the rumors of the Temple of the Atal'Hakkar are true? \n\nYour victory inside of da Sunken Temple will be remembered by da Zandalari for a long time, mon. This bone.. it be an odd choice to deliver us.. but no doubt was one used to summon Hakkar into da physical world -- it will be in good hands now, {name}. We no longer have to worry about Hakkar coming back thanks to your efforts, mon... right?", sourceObjectiveStatus = "unverified-source-field" }
quests[82084] = { id = 82084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Literacy", progress = "Your progress in the arcane arts has been exemplary, {name}. I think you are ready to author a spellbook of your own.\n\nLet's see... a quill from the Owlbeasts of the Hinterlands, and ink derived from silithid resin... yes, that will do. And for the pages, the finest Farraki Papyrus!", completion = "Your spellbook is ready, {name}. May you fill its pages with arcane secrets to rival the ancient libraries of Elun'dris and Zuldazar." }
quests[82086] = { id = 82086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Literacy" }
quests[82089] = { id = 82089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Transmutation", description = "Transmutation is a unique skill that all talented alchemists have access to, but only those most devoted to the art may learn to truly become masters at the art. You may have what it takes, but you'll need to prove to me your sincerity to pursue this path to greater knowledge and understanding.\n\nBring me three Arcanite Bars as a token of your devotion to this art.", sourceObjective = "Bring Crimeon Lablade three Arcanite Bars", progress = "Surely three paltry bars of arcanite are nothing in exchange for this knowledge?", completion = "Very well, I can see your devotion.\n\n<Crimeon stuffs the bars into his pack hastily>\n\nYes? Oh, transmutation. Of course. Hold very still, I need all of my concentration for this.\n\n<Crimeon waves his hands dramatically and a tiny spark shoots from his right index finger>\n\nWell, uh, yep. That should do it. Probably.", sourceObjectiveStatus = "unverified-source-field" }
quests[82090] = { id = 82090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mixology For Fun and Profit", description = "Any alchemist worth their salt will tell you that the art is all about maximizing profit margins. It's all about soucring materials cheap, crafting in bulk, and selling sky high. What if I told you there was a way to make your materials go much, much further? Well, as the self-proclaimed \"Master of Mixology\" I've got just what you need if you want to level up your elixir and potion game. Bring me 10 Invisibility Potions, 10 Elixirs of Demonslaying, and 5 Elixir of Sages and I'll show you the ropes.", sourceObjective = "Bring Mixmaster Blix 10 Invisibility Potions, 10 Elixir of Demonslaying, and 5 Elixir of Sages.", progress = "Look I've got a lot of potential students waiting around to learn from me. Do you have what I asked for? If not, beat it.", completion = "Oh wow you actually brought that stuff? Well, alright then. Let's cook that noodle of yours and make you a proper mixologist.", sourceObjectiveStatus = "unverified-source-field" }
quests[82093] = { id = 82093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jungle Durian", progress = "The bold and pungent smelling fruit will keep your spirits high while you traverse through the Swamp of Sorrows and explore the Temple of Atal'Hakkar. Don't let the odor fool you mon, this is a prized fruit of my people! \n\nIf you bring me back something enticing from your adventures, I'll make it worth your while, mon. A bundle of our finest durian for your troubles! Shall we make a deal?", completion = "Taz'dingo! Enjoy the delicious, sweet durian, but remember mon... no refunds." }
quests[82094] = { id = 82094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signets of the Lost Temple", progress = "For de most powerful adventurer, I offer de most powerful trades. I have somethin' that enhances your shoulder items, power from de Atal'ai themselves! {name}, if you have mojo found by the strongest of dere Atal'ai in da temple, I will make it worth your while. \n\nLet's not be too hasty now, I offer da fairest deals...", completion = "Be goin' now, mon. If ya need more of da goods, you know where to find me, {name}!" }
quests[82095] = { id = 82095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The God Hakkar", description = "Now it is time to capture the essence of the avatar of Hakkar.\n\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.\n\nBe warned, even in this nascent form he will wield unimaginable power and he will resist you with every ounce of his fury.\n\nDefeat him, and place his essence within the Egg of Hakkar.", sourceObjective = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", progress = "Have you defeated the avatar of Hakkar, {name}?  Has his essence yet empowered the egg I gave you?", completion = "The essence of Hakkar has been collected!  Even now the Egg stirs with life!  Could the myths of Hakkar be true?\n\nThat must not be true, for it is then I fear what Hakkar may do if birthed again.  I will keep this egg safe and be sure it does not fall into evil hands.\n\nYour labors with me are finished, {name}.  You have touched a legend, and your actions may one day change the face of our world.", sourceObjectiveStatus = "unverified-source-field" }
quests[82096] = { id = 82096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Depths", description = "Inside the temple, I found a circular room with six balconies, each one with a serpent statue on the edge. Curious, I pushed one of them to see what would happen, and it was a trap! I nearly fell to my death from the explosion. Laying there on the ledge, I looked down and noticed that there was another statue at the base of the room; an altar of sorts... Hakkar, I think it was called.\n\nI think that this altar is the secret -- you must bring this token to the altar in the Sunken Temple.", sourceObjective = "Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.", progress = "Upon examining the statue, you notice a depression in its side, just the size of the token that Marvon gave you...", completion = "You push the stone circle into the opening, and you hear it lock into place.\n\nNow that the stone is in place, you may continue... but what should you do next?\n\nPerhaps you should examine this altar further...", sourceObjectiveStatus = "unverified-source-field" }
quests[82097] = { id = 82097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret of the Circle", description = "My memories are cloudy, but I will tell you what I can. The circle of statues in the Sunken Temple, while dangerous, I believe that they hold the secret to unlock an even greater treasure.\n\nFrom the main altar, I was able to activate a series of lights. I think that if you can uncover what these lights mean, you might be able to unlock whatever secrets are hiding in this room.\n\nI warn you though, {name}. Great evil lies in the temple. It's likely that anything valuable will be fervently guarded...", sourceObjective = "Travel into the Sunken Temple and discover the secret hidden in the circle of statues.", completion = "The eye of the idol glitters brightly atop the ruined pile. Its transparency reveals something shiny behind it. You shift a few large chunks of rubble and manage to pull loose what lies beneath.\n\nThe Atal'ai treasure is now yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[82098] = { id = 82098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Temple of Atal'Hakkar", description = "According to legend, The Temple of Atal'Hakkar is a holy shrine dedicated to the ancient god, Hakkar the Soulflayer. Maintained by a vicious tribe of trolls named the Atal'ai, the temple is rumored to be impenetrable.\n\nNow sunk beneath the Pool of Tears, retrieving artifacts from the temple is even more difficult. But that's what I need you to do, {name}.\n\nAid me by gathering the intact Atal'ai Tablets. Bring them to me and I will return to the Explorers' Guild a hero. Together we will share the glory.", sourceObjective = "Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind.", progress = "As dusk slowly descends upon my career I turn to you, {name}, to help me in my final quest for the Explorers' League. If my old bones could muster the strength to brave the Swamp of Sorrows and the sunken temple I would be fighting right alongside you.\n\nPride makes it hard for me to ask for your help in collecting the Atal'ai Tablets. But old age forces the necessity.\n\nPlease help me, {name}. I want to retire from the Explorers' League having completed their final bidding.", completion = "The Atal'ai Tablets! Thank you, {name}!\n\nOnce I deliver these to the Explorers' League our names shall go down in history together. You have helped an old dwarf fulfill his final obligation in life. For that I am eternally grateful.", sourceObjectiveStatus = "unverified-source-field" }
quests[82099] = { id = 82099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haze of Evil", description = "To tell you the truth, {name}, I've never seen any plants like this in my travels. Perhaps I should take a trip to this crater...\n\nAt any rate, I think I know just the thing Muigin's looking for -- Atal'ai haze. It's horrid stuff, hard to collect, but it's just what he needs to control the little monsters.\n\nYou'll need to visit the temple of Atal'Hakkar in the Swamp of Sorrows. The Atal'ai haze can be collected from the deep lurkers, murk worms, or oozes found there. Good luck, {name}!", sourceObjective = "Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater.", progress = "Larion's still not speaking to me! He sure knows how to hold a grudge.", completion = "I admit, I'm a bit hesitant to touch that stuff, {name}! But if Gregan says it'll work, then I'm willing to give it a try!", sourceObjectiveStatus = "unverified-source-field" }
quests[82100] = { id = 82100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of Atal'Hakkar", description = "So he spoke of Jammal'an's prophecy?\n\nThe Atal'ai spiritual leader believes once Hakkar returns to Azeroth from the Nether, the god will grant the Atal'ai tribe immortality.\n\nFoolish trickery to bring about a premature doomsday if you ask me.\n\nBut you say the exile spoke of enchanted fetishes? This concerns me greatly. If these are in fact the key to the Atal'ai ritual which caused this mess, we must understand their intrinsic powers.\n\nVenture into the Temple, and seize the fetishes!", sourceObjective = "Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.", progress = "If the Atal'ai fetishes hold the power to summon Hakkar and fulfill Jammal'an's prophecy they must be seized. Such powers must be understood by the Horde!", completion = "Brave {class}, you have proven yourself to be a great champion of the Horde.\n\nNow this collection of fetishes of Hakkar must be dealt with at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[82101] = { id = 82101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zapper Fuel", description = "You're in luck, {name}! I've been working on some of my own experiments while Marvon's been gone, and one of them is a short range bug zapper. With just a few adjustments, it should be great for ridding yourself of those Bloodpetal pests.\n\nI can let you have one of my zapper prototypes, but you'll still need to collect the fuel. You can get the necessary Atal'ai haze that the zapper needs in the temple of Atal'Hakkar. The deep lurkers, murk worms, or oozes are the ones you'll need to get it from.", sourceObjective = "Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge.", progress = "This is exhausting, {name}. Those things just won't leave me alone!", completion = "So, Marvon wasn't around? Well, show me what you got, anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[82102] = { id = 82102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Eranikus", description = "As you touch the gem, a deep voice resonates in your mind.\n\n\"Mortal, heed this plea.  I am Eranikus of the Green Dragonflight, keeper of this accursed temple.  My charge to ensure that the trolls never again bring forth their abomination of a god has for now ended in failure.  As I imbue this gem with part of my essence, I sense my grip on the Dream twisting into chaos.  Please - place this gem into the essence font in my lair, and let our magic there purge the taint from my psyche so that I may rest.\"", sourceObjective = "Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.", progress = "As you near the essence font that Eranikus told you of, his voice once again touches your mind.\n\n\"Yes mortal, this essence font will redeem what untainted element of my psyche remains imbued in this gem.  Place the gem inside the font, and let the magic of the Green Dragonflight cleanse the corruption and taint from my being.  Only then will I find true release, and only then will the Dragonflight be able to reassert their stewardship over the Atal'ai.\"", completion = "You place the gem inside the essence font.\n\n\"Thank you mortal, you have - no... this, this cannot be! No!  The corruption of this accursed god even taints the sanctity of a Green Dragonflight essence font!  No please, I feel my essence ripping from me!  THE PAIN!  I feel the grip of an eternal nightmare taking hold on me...\"\n\n\"Mortal, I implore you!  Find one of the Green Dragonflight to stop this... help me... I am chained in darkness... forever in agony... please do not torture...\"", sourceObjectiveStatus = "unverified-source-field" }
quests[82104] = { id = 82104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jammal'an the Prophet", description = "My Witherbark companions don't take kindly to strangers around their home.\n\nMe? I don't have a home anymore. I was exiled from my people, the great Atal'ai tribe of the Swamp of Sorrows.\n\nOur spiritual leader, Jammal'an, had what he called a prophecy. He believes the summoning of the god, Hakkar will bring the Atal'ai immortality.\n\nBut I urged caution. What if the prophecy was nothing more than manipulation?\n\nI want revenge for my exile. Bring me Jammal'an's head. Maybe then my people will be free.", sourceObjective = "The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.", progress = "Once Jammal'an has been removed, I stand a chance of returning to my people.\n\nWith Jammal'an as their spiritual leader, the Atal'ai face certain destruction.", completion = "Jammal'an's reckless trust of false visions led my people to their eternal doom.\n\nI thank you, {class}, for avenging my exile. I mourn for my people. I have no home to return to.", sourceObjectiveStatus = "unverified-source-field" }
quests[82106] = { id = 82106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging the Mightstone", description = "Now we must combine the inert scourgestones and create a weapon to shatter the ranks of undead.  This is no trivial task, {name}.  Only the trolls of the sunken temple carry the kind of rare magic able to turn the evil of something against itself.\n\nIn the temple, the trolls are known as Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Do not feel remorse for their corrupt souls... they are not without evil.", sourceObjective = "Bring the voodoo feathers to Ashlam Valorfist.", progress = "Have you slain the wretched trolls?", completion = "This is excellent, {name}.  I would say I am surprised, but I knew without question that you wouldn't let us down.\n\nIt is my honor to bestow one of the Holy Mightstones to you.  Use it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[82107] = { id = 82107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodoo Feathers", description = "Your honor has brought some peace to me.  It is only right that I offer you something in return.\n\nMy weapons and armor were splendid in life, and yet they are of no use to me now.  They would be better served in your possession.\n\nTravel to the sunken temple and destroy the troll guardians Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  They carry magic feathers that can reform my physical body long enough to grant you a reward.", sourceObjective = "Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde.", progress = "Are you back so soon?  Time is not the same to me any more, perhaps it has indeed been a long journey for you...", completion = "At last I can feel the cold touch of steel again, even if only for a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[82108] = { id = 82108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Green Drake", description = "Now I set you on a dangerous hunt to slay the green drake, Morphaz, and bring his tooth to me.  Morphaz dwells deep in Temple of Atal'Hakkar, the entrance to which lies in Swamp of Sorrows.\n\nIf you wish to defeat him, you must not go alone.  This drake is an enemy of many -- seek others who wish to destroy him.\n\nThe drake's tooth represents the power a hunter will find in the company of others.  Bring it to me and you will have learned much.", sourceObjective = "Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", progress = "I see wisdom in your eyes, {name}.  Has your hunt ended?", completion = "You have learned the old ways, {name}, and for that I offer you a gift from my days as a {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[82110] = { id = 82110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azure Key", description = "It will take some time to decipher the fragments and remove the enchantment.  When I am complete, I'll deliver the bag to Lord Ravenholdt personally.\n\nThere is still the matter of the key, said to be held by a green drake known as Morphaz.  The drake has made its home deep in the Temple of Atal'Hakkar, the entrance to which lies in the Swamp of Sorrows.\n\nGather your friends and venture to his lair.  Lord Ravenholdt will await your return with the key.", sourceObjective = "Return the Azure Key to Lord Jorach Ravenholdt.", progress = "The bag has already arrived from Archmage Xylem, have you found the key?", completion = "The key!  I thought it lost forever.  Please, take an enchanted garment from my stores -- they are reserved for rogues of exceptional skill and loyalty.  It should be known that {name} is not to be trifled with!", sourceObjectiveStatus = "unverified-source-field" }
quests[82111] = { id = 82111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of Morphaz", description = "Now the last part, the second cure.\n\nThe green drake Morphaz is known to be immune to all forms of poison and disease -- many druids died to bring us this information.  There is no doubt his blood is potent for our needs.\n\nA courier from the Cenarion Circle will take the parts you have already collected while you gather the last.  Summon your allies and seek out the drake's lair in the sunken temple of Atal'Hakkar.  Bring his blood to Greta Mosshoof in Felwood.", sourceObjective = "Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows.", progress = "Do you have the blood of Morphaz?", completion = "You have slain Morphaz and carried his blood to us...  I can hardly believe this good news!\n\nWe will combine the ingredients at once and begin healing the trees and creatures of Felwood.  It will take a lifetime to undo what has happened here, but you have given us the means to do it.", sourceObjectiveStatus = "unverified-source-field" }
quests[82112] = { id = 82112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Better Ingredient", description = "It is as I feared -- the toxin is simply too weak for such a powerful creature.\n\nIf we are to create a toxin of high enough potency, you must venture to the bottom of the Temple of Atal'Hakkar, unlock the secrets of the altar and recover a putrid vine from the guardian there.  The temple is dangerous, and it would behoove you to bring friends.\n\nReturn to me when this is done.", sourceObjective = "Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder.", progress = "Have you recovered the vine?", completion = "At last, the toxin can be created in full.  I dare not require you to inflict it upon the creature again, as I have asked too much already.\n\nYou have my thanks and respect.  May you be well in your travels, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[82113] = { id = 82113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Voodoo", description = "The spirit totem just isn't enough.  We be needin' some voodoo magic to make it work jus' right.\n\nThe trolls in the sunken temple have feathers strong with voodoo magics.  Go there and kill Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Then we have magic enough for a real spirit totem.", sourceObjective = "Bring the voodoo feathers to Bath'rah the Windwatcher.", progress = "Where's the feathers, mon?", completion = "It's about time this troll got a full night's rest!  The spirit totem will watch over me.\n\nI been a long time collectin' things, maybe you want somethin' for all your trouble?", sourceObjectiveStatus = "unverified-source-field" }
quests[82114] = { id = 82114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy Morphaz", description = "There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz.\n\nYears ago, he overwhelmed me in a bold ambush and consumed my apprentice whole.  While the loss of an apprentice is not unknown to me, this particular one carried an arcane shard of unsurpassed size and quality.\n\nYou must gather powerful allies and delve into the temple.  Destroy Morphaz and recover the arcane shard from his ageless stomach.", sourceObjective = "Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.", progress = "Have you slain my old nemesis?", completion = "Incredible.  The shard has grown as it absorbed the drake's energy over the long years.\n\nThere is no more I can ask of you now.  My full ability to forge the arcane has returned with this shard.  My first creation is yours, {name}, and you have but to choose...", sourceObjectiveStatus = "unverified-source-field" }
quests[82115] = { id = 82115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolls of a Feather", description = "My pet is almost done.  Now I just need something to stuff it with.\n\nOnly the voodoo feathers from the trolls in the sunken temple will do.  They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Kill them.  Kill them all.\n\nThis is no trivial task {name}, so I'll make it worth your while by giving you something of Niby's -- he probably doesn't need it anyhow.", sourceObjective = "Bring a total of 6 Voodoo Feathers from the trolls in sunken temple.", progress = "Did you bring the feathers?  This doll needs stuffed!", completion = "Wonderful, now my pet is complete!\n\n<Impsy quickly stuffs the doll and gives it a demonic hug.>\n\nOh, what an odd side effect these voodoo feathers have...", sourceObjectiveStatus = "unverified-source-field" }
quests[82135] = { id = 82135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price of Hope", description = "<Aeonas says nothing, he merely hands you the orb and turns away>", sourceObjective = "Bring the Mannoroc Echoing Orb to Katherine the Pure in Stormwind.", progress = "Welcome back, {name}. What is that you have there... \n\nOh my.", completion = "That is quite the troubling tale. The part of me that is a {class} finds it impossible to reconcile that he willingly consorted with a member of the scourge... but the {race} part of me understands how strong the bonds of friendship can be. \n\nI thank you for bringing the orb here. I will see that it is stored in the deepest vault we have for now. \n\nOh, One last thing, I had this repaired and had hoped to present it to Aeonas on his return. I think he would want you to wield it in his stead.", sourceObjectiveStatus = "unverified-source-field" }
quests[82208] = { id = 82208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greater Friend of the Library", sourceObjective = "Thanks to your donations, the library is thriving.\n\nPlease, take this.", sourceObjectiveStatus = "unverified-source-field" }
quests[82209] = { id = 82209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water Pouch Bounty", progress = "Back again, {name}?  If you have five more Wastewander water pouches, then I have a care package with your name on it!", completion = "Excellent - the more water pouches we are able to reclaim, the further away from disaster we'll all be!  Keep 'em coming, and I will be sure to reward you for every five water pouches you bring me." }
quests[82210] = { id = 82210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Necklace Bounty", progress = "You've done it already, but we will continue to accept any troll tribal necklaces you find and are willing to turn in.  By turning them in to me, you'll continue to improve your standing amongst the Wildhammers; if you're willing to fight for us, then we'll be willing to fight for you!\n\nI need five troll tribal necklaces for them to count, {name}.", completion = "Another set of necklaces means that there are fewer trolls in the Hinterlands we have to worry about!  You've done it again, {name}.  Keep up the good work!" }
quests[82271] = { id = 82271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Glowing Scorpid Blood", progress = "That scorpid blood is working out great, {name}!  It's amazing how a little sparkle and shine can create a prized bauble out of an otherwise piece of junk.  The patrons love the stuff, and love is what it's all about, don't you think...\n\nYou've been a big help to me, {name}, and although I don't have a great need for more glowing scorpid blood, if you bring me more then I'll still trade you some tickets.", completion = "Thanks again, {name}.  Here are your tickets!" }
quests[82272] = { id = 82272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glowing Scorpid Blood", progress = "In all my time working the Faire, I've learned a lot of things about customers.  Here's one of those nuggets of wisdom: customers love stuff that glows!  It doesn't matter what it is - you could take a broken chair leg and make it glow, and every child will come from miles around to get one!\n\nSo, {name}, I need glowing scorpid blood.  You can find it from the scorpids of Sillithus, or the Blasted Lands, or the Burning Steppes.", completion = "Great job, {name}!  Thanks a lot!  I'm going to make paint from this blood and turn all kinds of cheap junk into glowing treasure!\n\nHere are your tickets, and thanks again!" }
quests[82273] = { id = 82273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Bat Eyes", progress = "{name}, the attraction I'm designing will be the scariest event since Gnomeregan was overrun!  And it's largely thanks to you and all the baubles you've brought me.  Many, many thanks!\n\nI don't need much else, but... if you bring me more evil bat eyes from the bats of the Eastern Plaguelands... I might have more Darkmoon Faire tickets for you.", completion = "Thanks again, {name}.  Here are your tickets!" }
quests[82274] = { id = 82274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evil Bat Eyes", progress = "Do you ever find yourself wandering in a cave, late at night, looking for adventure?  You do?  Really?  Well, then you've seen the creepy eyes of bats staring at you from high up, waiting for you to let down your guard so they can suck your blood!\n\nScary thought, don't you think?  Of course!  It's no doubt that bat eyes are scary!\n\nWill you bring me some evil bat eyes, {name}?  I want them for... something I'm designing.  Something scary.\n\nYou can get them from the bats of the Eastern Plaguelands.", completion = "Great!  You got the eyes!  I hope hunting those bats was frightening for you, because if it scared a brave {class} like yourself, then those eyes will certainly scare our Faire visitors.\n\nTake these tickets, {name}, and thank you for your service." }
quests[82275] = { id = 82275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Black Mace", progress = "For my act as the strongest woman alive, I plan to accept items from the audience and smash them with a big, black mace!\n\nCan you make me a big black mace, {name}?", completion = "Ah, perfect!  This mace has a big, heavy head on it.  I bet I could smash just about anything with it.  I just hope I don't break it along with whatever I swing it against!\n\nHere are your tickets, {name}.  Enjoy your stay at the faire!" }
quests[82276] = { id = 82276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituals of Strength", progress = "{name}, in my quest to become the strongest woman alive, I have traveled the world and learned muscle building secrets from distant weight masters, strength gurus, and ancient manuals.  I now know forbidden exercises that would kill the weak and cripple the uninitiated!\n\nThese feats of strength and conditioning require training with the densest of grinding stones.  {name}, can you find or make some grinding stones and bring them to me?  I'll give you tickets if you do...", completion = "Thank you, {name}.  I will use these stones in a strength-gaining ritual I learned from an ancient tablet in the deepest jungles of Stranglethorn.\n\nIt is said that she who performs this sacred rite correctly will have the strength and endurance of ten Tauren!" }
quests[82277] = { id = 82277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Dense Grinding Stones", progress = "{name}, thank you for all the help you've given me.  I really can't thank you enough!\n\nAlthough my need is no longer great... if you bring me more dense grinding stones, I still have more Darkmoon Faire tickets for you.", completion = "Again, thank you {name}.  Please enjoy these tickets, and tell your friends about the Darkmoon Faire!" }
quests[82278] = { id = 82278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Thorium Widgets", progress = "{name}, you have been so good to us, bringing me goods without tiring.  You have my eternal thanks!\n\nAlthough our need for Thorium widgets is not as great as it was, you may still bring them to me and I will gladly trade them for Darkmoon Faire tickets.", completion = "Here you are, {name}.  Here are Darkmoon Faire tickets for your enjoyment.  Do not, as they say, spend them all in one place!" }
quests[82279] = { id = 82279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorium Widget", progress = "Yebb Nebblegear, like me, is working on a future attraction.  So amazing is this attraction, says Nebb, that it will draw folks from across the world... and it will make us all very, very rich!\n\nHe says he needs thorium widgets for its construction, and wants me to collect them for him.  So what do you say, {name}?  Do you know where to get thorium widgets?  If you're an engineer, can you make them?  Do you want to trade them for Darkmoon Faire tickets?", completion = "Ah, thank you, {name}!  Yebb will enjoy these widgets.  I don't know what he has planned for them, but Yebb's a clever little gnome.  He's clever, and maybe a little devious....\n\nIf only he liked the taste of humanoid flesh... he'd make a great troll!\n\nHere, {name}.  A deal's a deal, and these tickets are yours." }
quests[82280] = { id = 82280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanical Repair Kits", progress = "The biggest reason I can't open up my booth is that... everything's broken!  I need mechanical repair kits to fix all this stuff!\n\nCan you bring me those kits, {name}?  I'll trade you... kits for Darkmoon Faire tickets.  What do you say?", completion = "Thank you!  Now I can get to fixing things.\n\nIt's going to take a lot of repair kits and a lot of late nights to get everything in working order.  Sometimes I think it'd be better to get back to my roots and restart my career as a headhunter, but... the Faire has been good to me.\n\nTake these tickets, {name}, and have fun!" }
quests[82281] = { id = 82281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Armor Kits", progress = "{name}, I must thank you for all your help.  I have plenty of supplies, through no small efforts on your part, but if you wish to bring me more armor kits, then I will gladly trade them for Darkmoon Faire tickets.", completion = "There you are, {name}.  A fair trade.  Enjoy." }
quests[82282] = { id = 82282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor Kits", progress = "You might not realize this, but running a traveling carnival is costly!  Everything wears down so fast it's a wonder we can turn a profit.\n\nBecause of all those hidden costs, we're always looking for ways to maintain our equipment as cheaply as possible.  Our tents, for instance, tear regularly but I've found that leather armor kits make great patches.  Can you find and bring me some armor kits? That'll save us a bundle!  Do that, and I have a fistful of Darkmoon Faire tickets for you...", completion = "Great!  This will work great!  I just noticed a rip in a tent over yonder, and one of these armor kits is just what I need to patch it up!\n\nThank you very much, {name}.  These armor kits will save us a ton in repair costs.  Here are your tickets - you deserve them!" }
quests[82283] = { id = 82283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Boy and the Bearded Murloc", progress = "Yebb is working on other attractions for his zoo, including wet, swampy abodes for a boy raised by crocolisks, and perhaps for a murloc.  We will need nice, water-tight leggings so we won't get waterlogged during prop-ups and tear-downs.  For that job, I think turtlescale leggings will do the trick.\n\n{name}, can you make those leggings?  If you do, then a fat stack of Darkmoon Faire tickets will be your reward...", completion = "Great, you made them!  These will do nicely... I just hope I won't be the one to clean the crocolisk cage when the time comes.  Those beasts can be rather beastly, don't you think?\n\nHere are your tickets, {name}.  Enjoy them, and enjoy your stay at the Darkmoon Faire!" }
quests[82301] = { id = 82301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Treasure", sourceObjective = "Here ya go, boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[82302] = { id = 82302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Treasure", sourceObjective = "Here ya go, boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[82303] = { id = 82303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Treasure", sourceObjective = "Here ya go, boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[82307] = { id = 82307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[82308] = { id = 82308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[82309] = { id = 82309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[82316] = { id = 82316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seven Eyes I Seek...", progress = "Seven hidden eyes I seek... bring them to me and you too shall see.", completion = "You are seen..." }
quests[82323] = { id = 82323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vibrant Plumes", progress = "A person's imagination is an incredible thing.  It can make the smallest hill seem like the largest mountain.  It can make the most innocuous shadow appear cast by a horrible nightmare!\n\nWe at the Darkmoon Faire let our visitor's imaginations blossom!  But to help stretch their imaginations... sometimes we have to get tricky.\n\nI need vibrant plumes for one of my attractions.  You can get them from the birds of the more dangerous areas of Azeroth.  Bring me the plumes and many tickets will be yours!", completion = "Ah, the plumes!  They are amazing, don't you think!  It would be easy to spark one's imaginations with such beauties!\n\nYou do such charitable work, {name}.  The smiles on our visitors' faces when they see the show is a grand payment indeed, but please take these tickets as well." }
quests[82656] = { id = 82656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Vest", description = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest and the wildvine weave within it produces a product that offers maximum protection of the torso while allowing for potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  This is not an easy lesson, but it is one you certainly have the skill to complete.", sourceObjective = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.", progress = "Do you have the two Turtle Scale breastplates and gloves?  Also, don't forget the wildvine!\n\nEven with the earliest patterns, we learn that the fundamentals of shape translate well into more difficult garments.  Though different items, the shape of the Turtle Scale breastplates prepares you for the detailing needed to make a Wild Leather vest.\n\nAs you progress through your lessons, the skills I teach will become as art.", completion = "These are some very nice pieces here, {name}.  The craftsmanship and care put in to making these show you have chosen to dedicate yourself fully to these tasks.\n\nYou've met my requests, and with that comes your reward.  The knowledge of making Wild Leather vests is now yours!", sourceObjectiveStatus = "unverified-source-field" }
quests[82657] = { id = 82657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Vest", description = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest blends with the wildvine to produce a product that offers maximum protection of the torso while allowing for the potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  It's a tall order, but one you should have little difficulty in filling for me.", sourceObjective = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.", progress = "Do you have the two Turtle Scale breastplates and gloves I ordered?  Also, don't forget the wildvine!\n\nEven with the earliest patterns, we learn that the fundamentals of shape translate well into more difficult garments.  Though different items, the shape of the Turtle Scale breastplates prepares you for the detailing needed to make a Wild Leather vest.\n\nAnd the gloves... well, they're just for my own benefit.  Remember, you're working for me!", completion = "These are some very nice pieces here, {name}.  The craftsmanship and care put in to making these alone would fetch several silver more than the average piece made.\n\nYou've filled my order, and with that comes your reward.  The knowledge of making Wild Leather vests is now yours!", sourceObjectiveStatus = "unverified-source-field" }
quests[82662] = { id = 82662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way of the Weaponsmith", description = "As a weaponsmith you'll find that more often than not, heroes and adventurers will be coming to you for gear. While the workload can be unbearable at times, the riches more than make up for the back strain and ash lung.\n\nOh yes, {name}, weaponsmiths are the ones with all the gold!\n\nIf you wish to join our ranks, you'll need to show me that you can make me a silver or two - I mean, show me that you've got what it takes to be the go to <guy/girl> when people need superior quality weapons. Get to work!", sourceObjective = "To become a Weaponsmith, you must make the following items and return them to Ironus: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces.", progress = "<Ironus is busy stacking gold coins into neat little piles.>", completion = "About time! I've got customers waiting.\n\nGive those here and pay attention. You're going to take the first step in your career as a weaponsmith.", sourceObjectiveStatus = "unverified-source-field" }
quests[82665] = { id = 82665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way of the Weaponsmith", description = "One day, I will create a legendary hammer. A hammer fit for a Warchief!\n\nIt is my life's work, {name}. My passion. I recognize that you have the potential to be among us, one of us - a weaponsmith. I am the one that can help you harness that potential.\n\nA simple task is all that you must complete. Simple for one of your exceptional skill.", sourceObjective = "To become a Weaponsmith, you must make the following items and return them to Borgosh: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces.", progress = "For the glory of the Horde!", completion = "This is the final step before you begin your new career as a weaponsmith, {name}. Should you choose to back out, now would be your last chance. Otherwise, prepare to be consumed by knowledge!", sourceObjectiveStatus = "unverified-source-field" }
quests[82850] = { id = 82850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Oil", progress = "Fish Oil keeps the cogs of war turning! If you've got some for me, pal, I'll make it worth your while.", completion = "Thanks a lot, {name}. I'll put this to good use." }
quests[82851] = { id = 82851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Ordinance", progress = "Did ya know that in Dark Iron tradition, the Senate writes proposed laws on explosive shells? If the Emperor doesn't like the law... kaboom!\n\nWhy are you lookin' at me like that? Don't you trust your ol' pal Grizzby?", completion = "Thanks a lot, {name}. I'll put this to good use." }
quests[82853] = { id = 82853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder Turbochargers", progress = "It's bad luck that shipping lanes back to Kezan are so unreliable these days. Back home you can get Turbochargers by the dozen for a few copper. Fallin' off the shelves at every machine shop. Can't get rid of 'em fast enough.\n\nAnyway, if you've got a few Turbochargers you don't know what to do with, I'd be happy to take them off your hands!", completion = "Thanks a lot, {name}. I'll put this to good use." }
quests[83188] = { id = 83188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Treasure", sourceObjective = "Here ya go, boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[83189] = { id = 83189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Treasure", sourceObjective = "Here ya go, boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[83190] = { id = 83190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Treasure", sourceObjective = "Here ya go, boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[83191] = { id = 83191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Treasure", sourceObjective = "Here ya go, boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[83192] = { id = 83192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Treasure", sourceObjective = "Here ya go, boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[83808] = { id = 83808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In a Bind", description = "You nearly scared me to death! I heard you coming and was convinced the dead had finally sniffed me out! All the same, you are a sight for sore eyes.  Please, I need to escape this place and find my master, Sir Dalton. May you retrieve my weapon for me? It was torn from my grip in the field outside and I was forced to flee into this barn.", sourceObjective = "Retrieve Squire Cuthbert's sword in the field to the south and return it to him.", progress = "Have you retrieved the blade?", completion = "Thank you, {class}.  I can't express my gratitude for your aid.\n\nI need but a moment to gather my wits about me. I took a terrible blow to the head out there and I'm not sure how well I can fight just yet. Oh light help me, I hope Sir Dalton is safe.", sourceObjectiveStatus = "unverified-source-field" }
quests[83822] = { id = 83822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Knight", description = "You say you found his... body? No... my lord cannot be dead. Our work is not yet finished. \n\nI... thank you, {class}. I'm struggling to shake of the shock of it, but I am glad that you were the one to find him.\n\nIt seems that his quest now falls to me. First however, I must return to his body and burn it lest he become the very thing he sought to destroy. If I may impose upon you once more, would you please lead me to the place where Sir Dalton fell?", sourceObjective = "Lead Squire Cuthbert to the body of the Fallen Knight you found earlier and help him burn the corpse. \n\nIf you lose Squire Cuthbert he will make his way back to his hiding place in the barn at Dalson's Tears and wait for you there.", progress = "<Squire Cuthbert's eyes seem to stare directly through the body of the fallen knight. He is trembling slightly.>", completion = "It seems I am again in your debt, {class}. Even seeing his body like that, it's hard to believe this is real. I've been in Sir Dalton's service since I was a boy, but I feel like I still have so much to learn if I wish to finish what Sir Dalton started.\n\nI cannot hope to keep you now. You've already honored me beyond measure with your kind aid. Please, let me impose upon you no longer. I will find my way from here, somehow.", sourceObjectiveStatus = "unverified-source-field" }
quests[83823] = { id = 83823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Violence", description = "Your technique is very interesting,{name}. A bit rougher around the edges than Sir Dalton, but it has a more \"worldly\" quality to it that I feel suits me well. Thank you so much, I've already learned so much from you!", progress = "Your technique is most impressive! A bit rougher around the edges than Sir Dalton, but it has a more \"worldly\" quality to it that I feel suits you well. Thank you so much, I've already learned so much from you and cant wait to apply it against our foe!", completion = "Your squire has grown in skill adventuring alongside you!" }
quests[83934] = { id = 83934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Me The Money!", description = "Heya! You look like the \"resourceful adventurer\" type so maybe you can help me out. See, my brothers and I came from the Lost Isles looking to start up a new business venture but we ran afoul of some pirates who stole our startup money. The people who are funding our operation back home aren't exactly what I'd call understanding, so we'd make it worth your while if are able to find any of the coin and return it. It's no ordinary gold but you should know it when you see it.", sourceObjective = "Bring a Tarnished Undermine Real to Pix Xizzix in Booty Bay.", progress = "Whatcha got for me, {race}?", completion = "Hey! That's great! \n\nIf you find anymore of our coin, come see me. We've got a great selection of goods and we'd be happy to barter!", sourceObjectiveStatus = "unverified-source-field" }
quests[83935] = { id = 83935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Path", description = "The pounding in my head has subsided somewhat, but I don't think I can fight my way out of here on my own yet. I hate to ask more of you, but could you help thin the ranks and clear a path for me to make my escape?", sourceObjective = "Kill 5 Blighted Zombies, 10 Skeletal Terrors, and 10 Rotting Cadavers to help clear a path for Squire Cuthbert to escape.", progress = "The coast is clear?", completion = "Thank you again, {class}. If we had someone like you with us when we were ambushed, I'm quite sure the ambush would have turned into a rout against our attackers in minutes!\n\nI've got my second wind now and must find Sir Dalton. He is a most skilled knight, but I am sure he needs my aid. Tell me, have you seen him out there? He's hard to miss in his gleaming white plate armor.", sourceObjectiveStatus = "unverified-source-field" }
quests[83936] = { id = 83936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalton's Quest", description = "<Squire Cuthbert stares blankly at the spot where Dalton's body burns. He is clearly in a kind of shock. You can tell that he is no fit state to continue on whatever quest he and his lord set out to complete. Perhaps you should speak with him and see if you can be of more aid?>", sourceObjective = "Speak with Squire Cuthbert to learn more about Sir Dalton's quest.", progress = "I... thank you.", completion = "I... don't know what to say. Despite the dour circumstances, it is beyond good fortune I find myself in the service another true hero of the Alliance. I can only hope that I am able to serve you better than I served Sir Dalton. \n\nLead on, hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[84008] = { id = 84008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Grace", description = "Your technique is very interesting,{name}. A bit rougher around the edges than Sir Dalton, but it has a more \"worldly\" quality to it that I feel suits me well. Thank you so much, I've already learned so much from you!", progress = "Through your teachings I feel more connected to the light than ever. I am starting to understand that the role of a {class} is to embrace mercy as much as it is to hone their martial prowess. I will consider this lesson well, and apply what I've learn to bolster our allies!", completion = "Your squire has grown in skill adventuring alongside you!" }
quests[84011] = { id = 84011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Star Lotus", description = "We still need more Star Lotus to reverse the Nightmare Incursions. Travel through the Emerald Portal in Seradane and bring me back some.", sourceObjective = "Gather 10 Star Lotus in the Hinterlands Nightmare Incursions and return to Field Captain Korlian.", progress = "You have the Star Lotus?", completion = "Well done! Thank you. Your services will be remembered.", sourceObjectiveStatus = "unverified-source-field" }
quests[84012] = { id = 84012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Starsilver Ore", description = "We still need more Starsilver Ore to reverse the Nightmare Incursions. Travel through the Emerald Portal in Seradane and bring me back some.", sourceObjective = "Gather 10 Starsilver Ore in the Hinterlands Nightmare Incursions and return to Field Captain Korlian.", progress = "You have the Starsilver Ore?", completion = "Well done! Thank you. Your services will be remembered.", sourceObjectiveStatus = "unverified-source-field" }
quests[84013] = { id = 84013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Starshells", description = "We still need more Starshells to reverse the Nightmare Incursions. Travel through the Emerald Portal in Seradane and bring me back some.", sourceObjective = "Gather 10 Starshells in the Hinterlands Nightmare Incursions and return to Field Captain Korlian.", progress = "You have the Starshells?", completion = "Well done! Thank you. Your services will be remembered.", sourceObjectiveStatus = "unverified-source-field" }
quests[84014] = { id = 84014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Moonroot", description = "We still need more Moonroot to reverse the Nightmare Incursions. Travel through the Emerald Portal in Dream Bough and bring me back some.", sourceObjective = "Gather 10 Moonroot in the Feralas Nightmare Incursions and return to Field Captain Arunnel.", progress = "You have the Moonroot?", completion = "Well done! Thank you. Your services will be remembered.", sourceObjectiveStatus = "unverified-source-field" }
quests[84015] = { id = 84015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Greater Moonstones", description = "We still need more Greater Moonstones to reverse the Nightmare Incursions. Travel through the Emerald Portal in Dream Bough and bring me back some.", sourceObjective = "Gather 10 Greater Moonstones in the Feralas Nightmare Incursions and return to Field Captain Arunnel.", progress = "You have the Greater Moonstones?", completion = "Well done! Thank you. Your services will be remembered.", sourceObjectiveStatus = "unverified-source-field" }
quests[84016] = { id = 84016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Moondragon Scales", description = "We still need more Moondragon Scales to reverse the Nightmare Incursions. Travel through the Emerald Portal in Dream Bough and bring me back some.", sourceObjective = "Gather 10 Moondragon Scales in the Feralas Nightmare Incursions and return to Field Captain Arunnel.", progress = "You have the Moondragon Scales?", completion = "Well done! Thank you. Your services will be remembered.", sourceObjectiveStatus = "unverified-source-field" }
quests[84017] = { id = 84017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time to Kill", description = "I feel that I've learned so much in so short a time. I don't think anyone could ever truly be ready to face what I intend to face, but I feel as ready as I'll ever be. What say you, {name}? Shall we go and end this fight? \n\nI'm not sure where to begin, but I suspect we'll find clues somewhere in the Eastern Plaguelands. We should probably start in areas where the Cult of the Damned congregates.", sourceObjective = "Find Arkonos and end him.", progress = "Vengeance is near, I can feel it!", completion = "It seems that we've found our quarry, but he seems to be out of our reach. We must discover a way to reach him so that we may strike.", sourceObjectiveStatus = "unverified-source-field" }
quests[84124] = { id = 84124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of Valor", description = "The spectral champion yields and motions toward the altar.", sourceObjective = "Return to the Altar of Reverence", completion = "On the altar you honored, a majestic two-handed axe of gold and black rests beside a tome of battlefield legends.", sourceObjectiveStatus = "unverified-source-field" }
quests[84125] = { id = 84125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close Enough To Touch", description = "These vile necromancers and their tricks, it's disgusting. We must find a way to break through the barrier protecting Arkonos to end him!\n\nMany Cult of the Damned and Scourge spellcasters are known to carry a variety of fell implements and foci of dark magic. Perhaps some of the nearby Shadowmages or Dread Weavers may have something we could use to penetrate the shield?", sourceObjective = "Kill Shadowmages and Dread Weavers in the Noxious Glade and search their corpses for something that can help you break the shield protecting Arkonos.", progress = "What did you find, {name}?", completion = "Yes! This might just do it. Let us make haste back to the slaughterhouse and put this device to the test!", sourceObjectiveStatus = "unverified-source-field" }
quests[84126] = { id = 84126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish the Fight", description = "This might just be it, {name}. Dalton long studied the Cult of the Damned, and taught me of a number of blessings to use to thwart their magics. Thanks to your diligence in finishing my training, I believe I am now strong enough to impart such a benediction upon this device to purify its magic and use it to disrupt the barrier surrounding Akronos. \n\nCome, let us burn down that coward's shield and end him once and for all!", sourceObjective = "Kill Arkonos the Cursed", progress = "At last, vengeance.", completion = "I can scarcely believe we did it. I cannot thank you enough for the aid you've provided in this quest, {name}. \n\nNow that it's done.... I'm not sure what to do with myself. I've been so preoccupied with our mission of late I've not stopped to think of what comes after. I think, for now, that I'd like some time to think. For now, I'm content to continue our adventures together, if you'll  have me. I've learned much, but I still think I have more to learn from you.", sourceObjectiveStatus = "unverified-source-field" }
quests[84135] = { id = 84135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beach Bot", description = "Lying on the shore, half-lost in the afternoon spray, is a strange metal contraption. It looks like some kind of mech, but you have never seen anything like it before. You notice a label on its side that reads \"Property of D.E.L.T.A.: Deepsea Exploration and Liquefaction Technologies Alliance\". You also spot a small compartment that you might be able to open.", sourceObjective = "Use a rock or something to dislodge parts of the mech.", completion = "Using your weapon and field skills you pry the compartment free, revealing a vial of glowing liquid within.", sourceObjectiveStatus = "unverified-source-field" }
quests[84136] = { id = 84136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beast Master of Moonglade", description = "While I'm tracking Van Amburgh, you could visit an old associate of mine. Banteazo is in Moonglade, where she studies animal behavior with the druids in order to refine training for companions. She's also fought Van Amburgh before and might have some pointers. Say hello to her for me!\n\nOnce you finish, we'll meet up again in Winterspring, where I plan to follow up some leads. I have an old camp in the northern hills where we can talk privately.", sourceObjective = "Travel to the village of Nighthaven in Moonglade, on Kalimdor. Seek out the troll Banteazo, a hunter, and ask her for insight into beast mastery.", completion = "You say dat Estelenn says hello? Odd, I've not seen dat Alliance flitterbug since da last time we traded arrows in Stranglethorn Vale... well, regardless, dis place is neutral ground. If she sent you to me, den you be here to talk about animals, yah?", sourceObjectiveStatus = "unverified-source-field" }
quests[84137] = { id = 84137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanical Romance", description = "You wonder why this mech was crashed here, and what this liquid is for. Maybe you can use it to reach the nearby islands and oil rig that seem to be connected to this mysterious organization. If there's one thing you know, it's that magical potions taste pretty good.", sourceObjective = "Find a use for the Guided Buoyancy Accelerant\n\nProvided item:", completion = "Reaching the oil rig, you spot a man in a lab coat tinkering with some robots. He notices you and shouts out while still fiddling with controls. \"Fantastic! You're just in time. I've been expecting you. You're the one who drank my wonderful potion, right? I'm Dr. Jurgens, and I have a proposition for you.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[84138] = { id = 84138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frosty Favors", description = "I'm the chief engineer, founder and head technician of the Deepsea Exploration and Liquefaction Technologies Alliance. I've nearly finished my latest experiment, and I need your help! I am working on a special device to geolocate resource-rich dimensions. To complete my construction, I need something back: a book of arcane formulas that I lent to an old colleague of mine, Numi, who continues her work in Winterspring. Retrieve the book for me and I'll reward you handsomely!", sourceObjective = "Explain the book situation to Doctor Jurgens' colleague, Numi, in Winterspring.", completion = "Sebastian needs it? He's a real piece of work. You're wasting your time asking for the book. I'm not giving it up or telling you where it is quite yet. But maybe we can make a deal.", sourceObjectiveStatus = "unverified-source-field" }
quests[84146] = { id = 84146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red Bag Blues", description = "What you want is safely hidden, and I can only hope the same can be said for what I'm looking for. I had a red bag containing some valuable exotics that I use for electro-optics. But, I lost it in a zeppelin accident over Burning Steppes! The bag could still be there, but with orcs, ogres, and poachers, I've had to put my work on hold. If you can locate it and bring it back to me, I'll let you have Jurgens' old book.", sourceObjective = "Locate the Red Bag that Numi in Everlook lost in a zeppelin mishap over Burning Steppes", completion = "You find the Red Bag laying on the table in a simple, carefree way.", sourceObjectiveStatus = "unverified-source-field" }
quests[84147] = { id = 84147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Well met, {class}.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", sourceObjective = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge.", progress = "Have you brought me what I requested of you, {name}?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces.", sourceObjectiveStatus = "unverified-source-field" }
