quests[84160] = { id = 84160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Hail, {class}!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.", sourceObjective = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Bindings of the Elements to Mokvar in Orgrimmar.", progress = "Have you obtained the items I require, {name}?", completion = "Ah, yes.  That old goblin shall be quite happy with this blood.\n\nThose bracers were part of a larger armor set.  If you're interested in providing me with further assistance I'd be willing to consider parting with the rest of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[84161] = { id = 84161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Hail, {class}!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.", sourceObjective = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Dreadmist Bracers to Mokvar in Orgrimmar.", progress = "Have you obtained the items I require, {name}?", completion = "Ah, yes.  Mux will be quite happy with this.\n\nThose bracers were part of a larger armor set.  If you're interested in providing me with further assistance,  I'd be willing to consider parting with the rest of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[84162] = { id = 84162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Hail, {class}!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.", sourceObjective = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Bracers of Valor to Mokvar in Orgrimmar.", progress = "Have you obtained the items I require, {name}?", completion = "Ah, yes.  Mux will be quite happy with this.\n\nThose bracers were part of a larger armor set.  If you're interested in providing me with further assistance,  I'd be willing to consider parting with the rest of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[84163] = { id = 84163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me the belt and set of gloves that you wish to upgrade.  I promise the ones I give you in return will be far superior.", sourceObjective = "Bring a Wildheart Belt and a set of Wildheart GlovesDeliana in Ironforge.", progress = "You're ready to perform the trade?", completion = "You've kept your end of the bargain, I shall keep mine.\n\nJust remember that I'm holding on to the best pieces until your work is finished.", sourceObjectiveStatus = "unverified-source-field" }
quests[84164] = { id = 84164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me an ordinary belt and a set of gloves that you wish to upgrade.", sourceObjective = "Bring a Beaststalker's Belt and a set of Beaststalker's Gloves to Deliana in Ironforge.", progress = "You're ready to perform the trade?", completion = "You've kept your end of the bargain, I shall keep mine.\n\nJust remember that I'm holding on to the best pieces until your work is finished.", sourceObjectiveStatus = "unverified-source-field" }
