quests[84179] = { id = 84179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Deliana in Ironforge with a set of Wildheart Boots, a Wildheart Kilt and Wildheart Spaulders.", progress = "You're back, {name}.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[84180] = { id = 84180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Deliana in Ironforge with a set of Beaststalker's Boots, Beaststalker's Pants and Beaststalker's Mantle.", progress = "You're back, {name}.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[84181] = { id = 84181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Deliana in Ironforge with a set of Magister's Boots, Magister's Leggings and Magister's Mantle.", progress = "You're back, {name}.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[84182] = { id = 84182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Deliana in Ironforge with a set of Lightforge Boots, Lightforge Legplates and Lightforge Spaulders.", progress = "You're back, {name}.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[84183] = { id = 84183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Deliana in Ironforge with a set of Devout Sandals, Devout Skirt and Devout Mantle.", progress = "You're back, {name}.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", sourceObjectiveStatus = "unverified-source-field" }
