quests[84201] = { id = 84201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Best for Last", description = "That's an amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.", sourceObjective = "Give Deliana your Dreadmist Mask and Dreadmist Robe.", progress = "As per our deal, are you ready to hand over your Dreadmist pieces in exchange for your new Deathmist Mask and Robe?", completion = "I'm going to miss you, {name}. I owe you such a debt of gratitude; I think I'll never be able to repay it.\n\nI hope that you enjoy your new head and chest armor, and that it protects you for a long time to come.", sourceObjectiveStatus = "unverified-source-field" }
