quests[84210] = { id = 84210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Best for Last", description = "A truly amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past.\n\nAs to your reward, I believe I have a few things that you have definitely earned and will truly enjoy.", sourceObjective = "Give Mokvar your Helm of Valor and Breastplate of Valor.", progress = "Are you ready to give me your Valor pieces in exchange for your new Helm and Breastplate of Heroism?", completion = "I will truly miss you, {name}. There is a debt that I owe you, which I may never be able to repay.\n\nEnjoy your new head and chest armor. May it protect you for a long time to come, and help you to achieve even greater honor!", sourceObjectiveStatus = "unverified-source-field" }
quests[84211] = { id = 84211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poacher's Den", description = "Picking up the bag, you immediately notice it's nearly empty. Somehow you get the impression Numi wont trade the book for the bag by itself. But what's not empty, is the camp. You'd better defend yourself and keep your eyes peeled for more of this stuff.", sourceObjective = "Defend yourself from poachers and recover the rest of Numi's materials.", progress = "Have you found the red bag yet? I need that stuff back if I'm going to finish these telescope upgrades in time for meteorite season!", completion = "Well, you turned out to be quite resourceful! These materials are irreplaceable to me. I can't thank you enough! Here, like I promised you, is the book Jurgens wants back. Please, take this hot beverage with you before leaving, it's cold out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[84212] = { id = 84212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bookin' it Back", description = "Numi hands over Jurgens' book. With it safely stowed, you begin the long journey back to the other side of the world.", sourceObjective = "Return to the D.E.L.T.A lab with the book Jurgens was looking for.", progress = "Did she keep the book?!", completion = "I see you have brought me the book I requested. Excellent! Your service is of profound scientific importance! We're nearly ready to harness geomantic energy and create a stable gateway to another dimension.", sourceObjectiveStatus = "unverified-source-field" }
quests[84213] = { id = 84213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rift Away", description = "Join me in this historic experiment and witness the wonders of my invention! I've calculated two locations with suitable geothermic bioflux energy. With manual-auto-locking phasers, I'm ready to send us to the coordinates within compatible regions.", sourceObjective = "Assist Doctor Jurgens with rift opening at either Tirisfal Glades or Westfall", completion = "Jurgens has gone missing in the chaos. You see a shimmering wafer within a cylindrical crystal container. Inside are the smashed-up remains of interior workings of the golem. You reach inside, unfasten wires from the housing, and open it.", sourceObjectiveStatus = "unverified-source-field" }
quests[84235] = { id = 84235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dive! Dive!", description = "You say you be looking for Van Amburgh? We can help each other.\nDa druids here are concerned about some heightened elemental activity. Da elementals be swarming about a fragment of pure elemental air, which manifests a whirlwind around it, on da south side of da lake.\n\nHead to da hills and retrieve da elemental fragment. Take my bat companion, Zotl, to fly into da winds, if you do not have a flying companion of your own. Zotl be hanging in da trees nearby.", sourceObjective = "Travel to the hills on the south side of Moonglade, on Kalimdor. Look for an air vortex east of the hills near the Timbermaw tunnel. Use the Dive skill of an animal companion to pierce the whirlwinds and retrieve a fragment of elemental air.", progress = "Have you taken da air fragment from da lake shore?", completion = "You have da air shard? Excellent work. You see how easy it is to work with your companions when you have a shared goal and you know what to do? You be allies in this.", sourceObjectiveStatus = "unverified-source-field" }
quests[84317] = { id = 84317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Midnight", description = "The towering titan envelops you in an aether aurora, wisdom and experiences of the ages joining your memories.", sourceObjective = "Gain astral insights", progress = "Moonlight cools your sweaty armor and nerves alike.", completion = "Magic-bound and shimmering, the tome floats in front of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[84318] = { id = 84318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oi!", description = "Oi! {class}! Yes, ye! Ye did me a solid by smashing up that depressin' mess of a meatsuit I've been riding in all these years, but I dinnae feel much of a pull to move on. I'm expectin' it's because I got some \"Unfinished Business\" to get up to 'afore I can be on me way. Well dull-wit, ye just been conscripted to help!\n\nI need ye to fetch me 'ammer. Should be somewhere in Corrin's Crossing and it'll be hard to miss. \n\nOi, take this too. It's me favorite gold tooth. Give it a rub when you've found me weapon.", sourceObjective = "Find Orthas' missing hammer in Corrin's Crossing.", progress = "Whadda want?", completion = "Aye I'm much obliged tae ye! Now that we've got that out of the way, let's work on puttin the rest together so you can send me on me way!", sourceObjectiveStatus = "unverified-source-field" }
quests[84319] = { id = 84319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh No Ye Don't!", description = "Great job with the hammer, {class}. Next up is me armor. Definitely need that back to move on to the great beyond.  \n\nOnly problem is it's in the eh... innards o' one of them 'bominations. I know, I know, it's askin' a lot, but ye gotta understand I was once a mighty thane under the mountain. I simply can't move on knowin' that the ancestral armor of me clan is dissolving in the gutjuice of a giant rotting mountain o' meat!", sourceObjective = "Orthas needs you to recover his missing armor from the corpse of an Abomination somewhere in Plaguewood.", progress = "Whadda want?", completion = "Oh that's nice! A little worse for wear but that'll do. We've one last thing needs doin'. I need a wee ritual. Just something tae put me scrambled spirit back together and send me on me way. This last part might be a bit discomfortin' for ye, bein a {class} and all, but trust me, it needs doin'! \n\nAt least it probably won't be more unsavory than fishin' around for me britches in abomination soup! Gwahaha!", sourceObjectiveStatus = "unverified-source-field" }
quests[84320] = { id = 84320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Heirloom", description = "I came to Stormwind as a refugee, fleeing the devastation brought to Lordaeron by the Scourge. I thank the Light that my family and I escaped, but some of our treasured heirlooms still remain in the Plaguelands.\n\nIf you are able to retrieve these heirlooms from their resting place in Sorrow Hill Crypt so I may safely inter them in the Cathedral's catacombs, I would be in your debt.", sourceObjective = "Retrieve the heirlooms from Sorrow Hill Crypt in Western Plaguelands, then return to High Priestess Laurena in Stormwind Cathedral.", progress = "Have you returned from the Plaguelands?", completion = "Thank you, {name}. You say you found a journal?", sourceObjectiveStatus = "unverified-source-field" }
quests[84321] = { id = 84321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic of Light", description = "I'm intrigued by the artifact mentioned in the journal you recovered. This may be what we need to turn the tide of battle against the Scourge.\n\nMost of the surviving records from Andorhal are under the Scarlet Crusade's protection in Hearthglen. Search through them and see if you can find more information.", sourceObjective = "Travel to Hearthglen in Western Plaguelands and search for information on the artifact described in the journal.", completion = "This ledger appears to hold records of Scarlet activity in the Plaguelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[84322] = { id = 84322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Research", description = "A page of the ledger catches your eye:\n\n\"Artifact - recovered near Sorrow Hill Crypt. Strong attunement to Light. Poor candidate for LW project due to warding properties and resistance to amplification enchantments. Delivered to Tyr's Hand for further study.\"", sourceObjective = "Search for the artifact within the Scarlet Crusade stronghold at Tyr's Hand in Eastern Plaguelands.", completion = "Opening the locker, you find a small box. Is this what you were looking for?", sourceObjectiveStatus = "unverified-source-field" }
quests[84323] = { id = 84323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prize Within", description = "Power radiates from inside the box. This must be the artifact! Now you just need to get it open...", sourceObjective = "Find a way to open the box and claim the artifact, then deliver it to High Priestess Laurena in Stormwind Cathedral.", progress = "What have you found, {name}?", completion = "So the story was true... I will hold on to this and investigate its potential. This could be the defense against the Scourge we need.\n\nTake this, {name}, with my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[84324] = { id = 84324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatic Overtures", description = "{name}, as I have studied the shard of light you brought, it has granted me visions. I see a priest of the Horde finding a similar shard, and I see the Alliance and Horde coming together in a surge of light.\n\nUnfortunately, our relations with the Horde have continued to decline.\n\nI suggest putting together a diplomatic gift as a gesture of cross-faith goodwill. Bring these supplies to me, and we will see if we can open a dialogue between our people.", sourceObjective = "Gather the supplies and deliver them to High Priestess Laurena in Stormwind Cathedral.", progress = "Do you have the supplies?", completion = "I will try and find a way to deliver this to Orgrimmar. \n\nI have something for you as well - this totem will provide healing to nearby members of the Horde. Acts of service may bridge the gap where words fail us.", sourceObjectiveStatus = "unverified-source-field" }
quests[84325] = { id = 84325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of Cooperation", description = "A panel at the base of the statue slides out, revealing a piece of parchment and a brilliant crystal similar to the one you discovered at Tyr's Hand.", sourceObjective = "Deliver the crystal to High Priestess Laurena in Stormwind Cathedral.", progress = "You have news for me?", completion = "Another shard of light! Where did you find this, {name}?\n\n\n\nI agree with the author. If the shards can be used as a weapon against the living as well as the undead, they could escalate the conflict between Alliance and Horde to a terrifying scale.", sourceObjectiveStatus = "unverified-source-field" }
quests[84326] = { id = 84326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomat Ring", description = "The diplomatic gift you assembled has reached the Forsaken priest Dietrich Praice, and I have made discreet contact with them. We both agree this search should be kept among the faithful. If the shards can be used as a weapon, it is best that they not fall into the hands of either faction's leaders.\n\nWe have devised a secret means of identification for those seeking the shards. Bring me materials to forge a ring that will contain a sliver of one of the shards.", sourceObjective = "Bring the requested materials to High Priestess Laurena in Stormwind Cathedral.", progress = "The cutting from the shard is ready, {name}. Do you have the other materials?", completion = "<With a conveniently quick spell, Laurena transmutes the materials and the gem cutting into a ring>\n\nUnfortunately, this was the easy part.", sourceObjectiveStatus = "unverified-source-field" }
quests[84327] = { id = 84327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Diplomatic Mission", description = "Your next task will be quite difficult, {name}. \n\nYou must make contact with a Horde priest who seeks the shards. You will identify each other with your rings. They will escort you into Orgrimmar, where you will need to speak with Dietrich Praice.\n\nIf you can convince the priests of the Horde that our intentions are peaceful, we may have a chance at reuniting the shards.", sourceObjective = "Make contact with a Horde Priest at the gates of Orgrimmar and gain Diplomatic Immunity by using your Diplomat Rings on each other. Then, enter Orgrimmar and speak to Dietrich Praice. You will lose Diplomatic Immunity if you stray too far from your escorting Priest or engage in combat.", completion = "You must be the {class} I was told to expect. I'm not sure whether to think you brave or foolish.", sourceObjectiveStatus = "unverified-source-field" }
quests[84328] = { id = 84328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repairing the Shard", description = "I am willing to believe you are here in good faith, {class}.\n\nWe are receptive to a meeting between our people. But the shard of light we possess is in poor condition. We must replenish it before any attempt at joining with the others.\n\nThe ancient Highborne of what is now Dire Maul were skilled in manipulating arcane and holy energies. Go there and find any information you can on artifacts of light, then return to me.", sourceObjective = "Retrieve the book \"Applied Divinity\" from Dire Maul, then return to Dietrich Praice in Orgrimmar.\n\nTo enter Orgrimmar, you will need the assistance of a Horde Priest with a Diplomat Ring to gain Diplomatic Immunity. You will lose Diplomatic Immunity if you stray too far from your escorting Priest or engage in combat.", progress = "You have returned, {class}?", completion = "This should help to repair the shard. The time has come to bring an end to this.", sourceObjectiveStatus = "unverified-source-field" }
quests[84329] = { id = 84329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Convocation Assembles", description = "Representatives from the faiths of both Alliance and Horde have agreed to meet and unite the shards. There is a chapel next to the ruined tower of Karazhan which will serve as neutral ground. \n\nYour ring contains the last shard. When you arrive, the convocation may commence.", sourceObjective = "Speak to Maethra Slagheart in Deadwind Pass.", completion = "The convocation's assembled, {name}. Now that yer here, we can begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[84330] = { id = 84330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wee Bit O' Necromancy", description = "So ye see, we need tae find a suitable Dwarf corpse and do a bit o' ritual to em' to get my spirit grounded so I can be sent on me way! All perfectly normal stuff, o' course! We'll also need a bit o' Necrotic Runestone from a necromancer type, of course. I hear there's one in Stratholme. Goes by Maleki the Pallid or some such. Can't expect he'll be too willin' tae part with it willingly but there's a solve fer that!\n\nGet me that stone and then head to the undercroft. There's a corpse there that'll do!", sourceObjective = "Obtain a Necrotic Runestone from Maleki the Pallid in Stratholme, then find the Rotting Dwarf Corpse near the Undercroft in southwestern Eastern Plaguelands.", progress = "...", completion = "<You reach down to touch the corpse and the hairs on the back of your neck stand on end... you have a bad feeling about this>", sourceObjectiveStatus = "unverified-source-field" }
quests[84331] = { id = 84331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Miracle", description = "The shards are gathered, {name}. All that remains is your ring.", sourceObjective = "Use your Diplomat Ring on the shards.", completion = "Although this being of Light did not speak, I felt its gratitude. Whatever it was, we have saved it.\n\nThe rifts between Alliance and Horde are deep, and many injustices have been wrought on both sides. But you have proven today that our greatest triumphs are earned together.\n\nYou have done enough, {name}. The next steps towards peace fall on myself and the other leaders that have gathered today.", sourceObjectiveStatus = "unverified-source-field" }
quests[84332] = { id = 84332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thane's Gratitude", description = "<You hear a disembodied voice in your head as you touch the small chest> \n\nCan't be thankin' ye enough, {name}. Not how ye'd be expecting it to turn out, no doubt! Just so you aren't too sour about it, I've got something fer ye that I've no more use for that I think ye might find useful.\n\nGood luck to ye, {name}. Ah, one last thing... if ye happen to see a giant floating necropolis in the distance someday soon, I'd be turnin' tail and runnin' if I were ye. Hah!You will learn:", sourceObjective = "You find a small runestone at the bottom of the chest...", sourceObjectiveStatus = "unverified-source-field" }
quests[84338] = { id = 84338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Binding Contract", description = "The undersigned hereby declares that the Sulfuron ingot they are delivering to the Thorium Brotherhood (TB Ltd.) is genuine and not a facsimile thereof. The undersigned also acknowledges that any harm that should come to <him/her> as a result of attempting to build, forge, find, create, sell, or eat Sulfuras, is not the responsibility or fault of TB Ltd.\n\nBy signing this contract, you are agreeing to all terms listed herein.\n\n_________________\n\nSignature", sourceObjective = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.", progress = "Do we have a deal?", completion = "It has been a pleasure doing business with you, {name}!\n\nOn behalf of TB Ltd., I wish you luck in your search for Sulfuras!", sourceObjectiveStatus = "unverified-source-field" }
quests[84348] = { id = 84348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priority Target: Duke Tectonis", description = "There's a particularly nasty elemental called Tectonis calling the shots near the base of blackrock mountain and he's just gotta go! Put an end to this pile o' rocks and report back to me when the deed is done!\n\nYou'll find Duke Tectonis in a valley to the southeast, near the entrance to Blackrock Mountain.", sourceObjective = "Hansel Heavyhands at Thorium Point wants you to destroy Duke Tectonis. Duke Tectonis can be found in a small valley just to the west of the Searing Gorge entrance to Blackrock Mountain.", completion = "This will set our enemies back for sure, {name}! Huzzah!", sourceObjectiveStatus = "unverified-source-field" }
quests[84349] = { id = 84349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priority Target: Duke Searbrand", description = "Our lookouts report that a firelord calling itself Duke Searbrand has been seen in the depths of the cauldron working hard to summon more fire elementals from the Firelands! We need you to get in there and put a stop to this before it gets out of hand.", sourceObjective = "Lookout Captain Lolo Longstrike wants you to destroy Duke Searbrand. You'll find Duke Searbrand in lowest depths of the Slag Pit caves, directly south of Thorium Point.", completion = "Well done {name}! After all that exertion, I think I need a drink! Hah!", sourceObjectiveStatus = "unverified-source-field" }
quests[84350] = { id = 84350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grinding Them Down", description = "We've got earth elementals coming out of our ears! Give them a proper clobbering and send them packing back to the Firelands!", sourceObjective = "Evonice Sootsmoker wants you to slay 10 Obsidian Reavers in the Searing Gorge. The Obsidian Reavers can be found all along the southern section of Searing Gorge, and near the entrance the Blackrock Mountain.", progress = "Did you give them what-for?", completion = "Hah! That'll show them!", sourceObjectiveStatus = "unverified-source-field" }
quests[84351] = { id = 84351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Smarter, Not Harder", description = "Ever since the eruptions started we've been fighting tooth and nail to keep these blasted elementals down and the work has taken its toll on our craftsmen. Turns out, keeping the troops' gear and kit in tip-top shape is a lot of work. Fortunately, us dwarves are the masters of working smarter, not harder and we've discovered that the power cores inside of the Obsidian Surgers to the southeast of Thorium Point can be put to great use as whetstones to easily hone our blades!  \n\nWould you fetch more for us?", sourceObjective = "Taskmaster Scrange wants you to slay Obsidian Surgers in the Searing Gorge and bring their Power Cores back him. Obsidian Surgers can be found along the southern portion of the Searing Gorge, near the entrance to Blackrock Mountain.", progress = "Eh?", completion = "That'll do nicely, {class}. Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[84355] = { id = 84355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Like Lame-bringers!", description = "As if we didn't have enough to deal with around here, the Twilight's Hammer enclave just west of Thorium Point has been right humming with activity since the mountain went and blew its top. Near as we can tell these new Flamebringers are the ones calling the shots now. \n\nWhy don't you trundle over there and put as many of them into the ground as you can.", sourceObjective = "Taskmaster Scrange wants you to slay Flamebringer Defenders and Flamebringer Elementalists at Firewatch Ridge to the west of Thorium Point.", progress = "How're things lookin' over at the ridge?", completion = "Good riddance!", sourceObjectiveStatus = "unverified-source-field" }
quests[84356] = { id = 84356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, Shiny!", description = "A group of Dark Irons were recently captured with some particularly curious enchanted gemstones on their persons. These gemstones don't appear to be native to Azeroth and I simply MUST study more of them! They have their slaves digging the stuff up now deep in The Cauldron, and I need ye to head down there as fast as ye can and bring me some additional samples. I'll make it worth your while if you do!", sourceObjective = "Master Smith Burninate at Thorium Point wants you to gather 8 Flamestone Clusters from Dark Iron Slavers in The Slag Pit. You can find the entrance to the Slag Pit inside the Cauldron, southeast of Thorium Point.", progress = "What'cha got for me?", completion = "They're beautiful! I can't wait to get these under my monoscope. Many thanks, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[84359] = { id = 84359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleepless Nights", description = "It's not enough that these curs attack us while we are awake, they also have to attack us while we sleep! The new Twilight Lord has a particular affinity for dream shenanigans so he's been sending assassins to attack us in our dreams! I need you to knock back a few mouthfuls of my specially formulated, locally sourced, non-GNO \"Dreamjuice\". That should allow you to straddle the line between the waking and dreaming world and stop these sneaks in their tracks.", sourceObjective = "Evonice Sootsmoker is asking you to drink the Specially Formulated Dreamjuice and slay 5 Flamebringer Stalkers near Thorium Point in the Searing Gorge.", progress = "Did ye give 'em what-for yet?", completion = "Well done, {name}. That should make 'em think twice before sneakin' into Thorium Point again!", sourceObjectiveStatus = "unverified-source-field" }
quests[84360] = { id = 84360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firefighting", description = "You there, you've just been conscripted! The fire elementals just won't stop pouring out of the Cauldron. I need you to get in there and cauterize the wound, if you take my meaning. Snap to it, soldier!", sourceObjective = "Overseer Oilfist wants you to slay 15 Firelands Invaders in The Cauldron, south of Thorium Point.", progress = "Well?", completion = "Well done, {name}. You got some grit, I'll give you that.", sourceObjectiveStatus = "unverified-source-field" }
quests[84369] = { id = 84369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing the Healer", description = "I am in need of your help. My flask was stolen from me by the corrupted treants of Irontree Woods in Felwood. The herbal mixture should help with my wounds, but it will not be enough alone. Bring it to the hot springs of Winterspring. The healing waters there will aid in my recovery.", sourceObjective = "Retrieve the Unusual Flask from the Irontree Stompers and bring it to the Frostfire Hot Springs in Winterspring.", progress = "You have made it, {name}.", completion = "Thank you, {class}. You have saved me much time in bringing my flask to me. With this, corruption will spread much quicker.\n\nUnfortunately, this will be the last time that you will be needed.", sourceObjectiveStatus = "unverified-source-field" }
quests[84372] = { id = 84372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lava Diving", description = "Our lookouts tell me there's a big glowing rock stickin' out of the deepest part of the lava pools beneath the Cauldron. The elementals seem to react to this material, so I need ye to sneak in there and grab me a chunk of that rock. It's pretty hot down there in more ways than one, so I suggest ye bring a hearty supply of fire protection potions!", sourceObjective = "Bring a chunk of Shimmering Molten Mineral to Hansel Heavyhands. You can find the shimmering molten crag within the Slag Pit lava pools, deep within the Cauldron.", progress = "What have ye got there?", completion = "Hopefully we can use this to learn a bit more about what we are dealing with.", sourceObjectiveStatus = "unverified-source-field" }
quests[84377] = { id = 84377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End of the Dark Horde", description = "The deed is done. Dal'rend Blackhand, Warchief of the Dark Horde, lies dead at your feet. Take his head and present it to Master Shaw.", sourceObjective = "Take the Head of Rend Blackhand to Master Mathias Shaw in Stormwind.", progress = "By the Light!", completion = "Well done, champion.  The Warchief of the Dark Horde is dead, ending an era of terror in our lands. Let all of Stormwind know of your victory!", sourceObjectiveStatus = "unverified-source-field" }
quests[84384] = { id = 84384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonic Deceptions", description = "De loa have told me of a poison gatherin' strength in Ashenvale, on the tainted land where the great demon Mannoroth was slain. Someone be drawin' power from the pit lord's remains.\n\nThey must be usin' illusions to hide their rituals. If you are to stop them, you'll be needin' protectin from their deceptions.\n\nMy tribe uses an extract from owlbeast glands in an enchantment to discern truth from lies. Collect these glands from the owlbeasts in Winterspring.", sourceObjective = "Collect 6 Owlbeast Pineal Glands from owlbeasts in Winterspring, then return to the Shadowtooth Emissary in Felwood.", progress = "The enchantment is almost ready, {name}. Did you bring what I asked for?", completion = "<The troll chants an incantation over an object, then hands it to you>\nTake this, {name}. It will protect you from the demons' illusions.", sourceObjectiveStatus = "unverified-source-field" }
quests[84394] = { id = 84394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greater Friend of the Library", sourceObjective = "Thanks to your donations, the library is thriving.\n\nPlease, take this.", sourceObjectiveStatus = "unverified-source-field" }
quests[84395] = { id = 84395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undead Potatoes", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[84396] = { id = 84396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magma or Lava?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[84397] = { id = 84397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Kalimdor - A Comprehensive Guide", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[84398] = { id = 84398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Study of the Light", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[84399] = { id = 84399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ka-Boom!", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[84400] = { id = 84400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Knight and the Lady", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[84401] = { id = 84401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge: Undead Menace or Misunderstood?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[84402] = { id = 84402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necromancy 101", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[84405] = { id = 84405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Heirloom", description = "Before the plague turned me, I was a merchant of some importance in Andorhal. The town likely interred my former wealth and family records in Sorrow Hill Crypt when they thought me gone.\n\nWould you be kind enough to retrieve my possessions from the crypt and return them to me?", sourceObjective = "Retrieve the heirlooms from Sorrow Hill Crypt in Western Plaguelands, then return to Dietrich Praice in Orgrimmar.", progress = "Have you returned from the Plaguelands?", completion = "Thank you, {name}. You say you found a journal?", sourceObjectiveStatus = "unverified-source-field" }
quests[84406] = { id = 84406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic of Light", description = "This weapon of light described in the journal troubles me. If the Scarlet Crusade or the Alliance were to obtain such a thing, it could be a serious threat to the Forsaken.\n\nMost of the surviving records from Andorhal are under the Scarlet Crusade's protection in Hearthglen. Search through them and see if you can find more information.", sourceObjective = "Travel to Hearthglen in Western Plaguelands and search for information on the artifact described in the journal.", completion = "This ledger appears to hold records of Scarlet activity in the Plaguelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[84407] = { id = 84407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prize Within", description = "Power radiates from inside the box. This must be the artifact! Now you just need to get it open...", sourceObjective = "Find a way to open the box and claim the artifact, then deliver it to Dietrich Praice in Orgrimmar.", progress = "What have you found, {name}?", completion = "So the story was true... I will hold on to this and investigate its potential. Not only our are enemies deprived of this weapon, but in our own hands it could prove a powerful defense against the Scourge.\n\nTake this, {name}, with my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[84408] = { id = 84408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatic Overtures", description = "{name}, as I have studied the shard of light you brought, it has granted me visions. I see a priest of the Alliance finding a similar shard, and I see the Alliance and Horde coming together in a surge of light.\n\nUnfortunately, the Alliance continues to treat us as little more than vermin.\n\nI suggest putting together a diplomatic gift as a gesture of cross-faith goodwill. Bring these supplies to me, and we will see if we can open a dialogue between our people.", sourceObjective = "Gather the supplies and deliver them to Dietrich Praice in Orgrimmar.", progress = "Do you have the supplies?", completion = "I will try and find a way to deliver this to Stormwind.\n\nI have something for you as well - this totem will provide healing to nearby members of the Alliance. Acts of service may bridge the gap where words fail us.", sourceObjectiveStatus = "unverified-source-field" }
quests[84410] = { id = 84410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of Cooperation", description = "A panel at the base of the statue slides out, revealing a piece of parchment and a brilliant crystal similar to the one you discovered at Tyr's Hand.", sourceObjective = "Deliver the crystal to Dietrich Praice in Orgrimmar.", progress = "You have news for me?", completion = "Another shard of light! Where did you find this, {name}?\n\n\n\nI agree with the author. If the shards can be used as a weapon against the living as well as the {race}, they could escalate the conflict between Alliance and Horde to a terrifying scale.", sourceObjectiveStatus = "unverified-source-field" }
quests[84411] = { id = 84411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomat Ring", description = "The diplomatic gift you assembled has reached High Priestess Laurena in Stormwind, and I have made discreet contact with them. We both agree this search should be kept among the faithful. If the shards can be used as a weapon, it is best that they not fall into the hands of either faction's leaders.\n\nWe have devised a secret means of identification for those seeking the shards. Bring me materials to forge a ring that will contain a sliver of one of the shards.", sourceObjective = "Bring the requested materials to Dietrich Praice in Orgrimmar.", progress = "The cutting from the shard is ready, {name}. Do you have the other materials?", completion = "<With a conveniently quick spell, Dietrich transmutes the materials and the gem cutting into a ring>\n\nUnfortunately, this was the easy part.", sourceObjectiveStatus = "unverified-source-field" }
quests[84412] = { id = 84412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Diplomatic Mission", description = "Your next task will be quite difficult, {name}. \n\nYou must make contact with an Alliance priest who seeks the shards. You will identify each other with your rings. They will escort you into Stormwind Cathedral, where you will need to speak with High Priestess Laurena.\n\nIf you can convince the priests of the Alliance that our intentions are peaceful, we may have a chance at reuniting the shards.", sourceObjective = "Make contact with an Alliance Priest at the gates of Stormwind and gain Diplomatic Immunity by using your Diplomat Rings on each other. Then, enter Stormwind Cathedral and speak to High Priestess Laurena. You will lose Diplomatic Immunity if you stray too far from your escorting Priest or engage in combat.", completion = "You must be the {class} I was told to expect. I hope my countrymen were polite, if not welcoming.", sourceObjectiveStatus = "unverified-source-field" }
quests[84413] = { id = 84413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repairing the Shard", description = "I am willing to believe you are here in good faith, {class}.\n\nWe are receptive to a meeting between our people. But the shard of light we possess is in poor condition. We must replenish it before any attempt at joining with the others.\n\nThe ancient Highborne of what is now Dire Maul were skilled in manipulating arcane and holy energies. Go there and find any information you can on artifacts of light, then return to me.", sourceObjective = "Retrieve the book \"Applied Divinity\" from Dire Maul, then return to High Priestess Laurena in Stormwind Cathedral.\n\nTo enter Stormwind, you will need the assistance of an Alliance Priest with a Diplomat Ring to gain Diplomatic Immunity. You will lose Diplomatic Immunity if you stray too far from your escorting Priest or engage in combat.", progress = "You have returned, {class}?", completion = "This should help to repair the shard. The time has come to bring an end to this.", sourceObjectiveStatus = "unverified-source-field" }
quests[84414] = { id = 84414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send Me On Me Way!", description = "<You hear the disembodied voice of Orthas in your mind>\n\n'Ere we are then. Let's get on with it, shall we?", sourceObjective = "Observe Orthas as he moves on from this world.", completion = "You have no words for what just happened. What have you done? \n\nHopefully there's at least some good loot in this chest.", sourceObjectiveStatus = "unverified-source-field" }
quests[84418] = { id = 84418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Knight", sourceObjective = "A mutual friend of ours recently reached out to ask for aid in locating a missing knight by the name of Dalton. He and his young squire were last seen in the plaguelands and have not been heard from in quite some time. If your travels take you that way, please keep an eye out for them.\n\nNot much to go on, but you have a knack for finding yourself in all sorts of interesting situations. If anyone could stumble upon a missing knight and his pup squire in the middle of those hellish plaguelands, it's you.", sourceObjectiveStatus = "unverified-source-field" }
quests[84495] = { id = 84495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Plate Gauntlets", description = "By Thaurissan's beard!\n\nWhere did you find them?\n\nMore importantly, are you willing to part with them? Naturally, I would pay you for such a noble gesture.\n\nI'll tell you what, {name}. If you give me those unfired gauntlets, I will teach you how to make a set all your own. All you need to do is collect the parts for me so that I may narrow down the exact recipe.\n\nDo we have a deal??\n\nHere's the list of what I need, I'll front the non-enchanted thorium myself since you're supplying the gauntlets.", sourceObjective = "Bring Malyfous Darkhammer 6 Enchanted Thorium Bars, 2 Essence of Fire, and 4 Star Rubies. You will also need to turn in your Unfired Plate Gauntlets.", progress = "Time is money, {name} and I don't have much of either.", completion = "As promised, {name}, here's your recipe! I'm also going to throw in a little something extra for all of your hard work and dedication. What am I going to do with these anyway???", sourceObjectiveStatus = "unverified-source-field" }
quests[84496] = { id = 84496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Serenity", description = "Within the confines of the Scarlet Bastion lies sweet Serenity. The Crimson Hammersmith guards the recipe with his life. Defeat him and bring me his apron. For that, I shall train you to become a hammersmith.\n\nUnderstand this: Once you have chosen the path of the hammersmith, the paths of the swordsmith and axesmith will no longer be available.", sourceObjective = "Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith.", progress = "His apron! Where is it?", completion = "So you are certain this is what you want? To become a hammersmith? Remember, the doors to becoming a swordsmith and axesmith will close forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[84525] = { id = 84525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Treasure", sourceObjective = "Here ya go, boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[84545] = { id = 84545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Reward", description = "{name}, your services to the Warlords surpassed all we could expect from the denizens of this world.\n\nWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.\n\nUnder the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward.\n\nGo, {name}.  Claim your reward.", sourceObjective = "Claim your reward from Hydraxis' Coffer.", completion = "Hydraxis' voice descends from the waters' surface...\n\n\"Choose that which best suits you, {name}.  May it protect you against the foes of the Waterlords.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[84546] = { id = 84546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stave of the Ancients", description = "Agents of the Burning Legion are still active in our world, {class}. These agents corrupt all that they touch. Nature wilts and weeps in their presence.\n\nYou must track down these demonic corrupters and destroy them, {name}. Be warned, you must engage them by yourself or they will flee. As long as you are alone, they will try and destroy you. You must strike at them, turning their arrogance into misery.\n\nI grant you a piece of my bark, the inscriptions shall lead you to your targets. Retrieve their heads.", sourceObjective = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself.", progress = "Do not be fooled by their disguises!", completion = "You have served us well, {name}! Take this stave and combine it with the bow string that Stoma is able to create. Together, they form a most formidable weapon.", sourceObjectiveStatus = "unverified-source-field" }
quests[84548] = { id = 84548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona: A Study on Stealth and Treachery", description = "The tome carries the mark of the Athenaeum.", sourceObjective = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Excellent work, {race}. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", sourceObjectiveStatus = "unverified-source-field" }
quests[84549] = { id = 84549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcanist's Cookbook", description = "The tome carries the mark of the Athenaeum.", sourceObjective = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Excellent work, {race}. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", sourceObjectiveStatus = "unverified-source-field" }
quests[84550] = { id = 84550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Codex of Defense", description = "The tome carries the mark of the Athenaeum.", sourceObjective = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Excellent work, {race}. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", sourceObjectiveStatus = "unverified-source-field" }
quests[84551] = { id = 84551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light and How To Swing It", description = "The tome carries the mark of the Athenaeum.", sourceObjective = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Excellent work, {race}. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", sourceObjectiveStatus = "unverified-source-field" }
quests[84555] = { id = 84555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nostro's Compendium", description = "You have uncovered something of great importance. This book is unlike any that you have seen.\n\nIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible.", sourceObjective = "Return Nostro's Compendium of Dragon Slaying to the Athenaeum.", progress = "Ah, one of our greatest compilations. This one has been missing for ages.", completion = "You could have gotten quite a lot of gold for this book on the black market, {name}. Especially since the protective seal has been broken, leaving the secrets of dragon slaying viewable to any with the requisite intellect to consume the knowledge held within the sacred pages.\n\nPerhaps a grand reward is in order... Well, a reward that will require enormous effort to obtain.", sourceObjectiveStatus = "unverified-source-field" }
quests[84556] = { id = 84556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forging of Quel'Serrar", description = "If you wish to take on this task, present Lydros with the dull blade.", sourceObjective = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.", progress = "Excellent, let us begin...", completion = "If you manage to enter the lair of the dragon, heat the blade under her fiery breath, and ultimately temper it in her blood, I shall bind the blade for your use.", sourceObjectiveStatus = "unverified-source-field" }
quests[84557] = { id = 84557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forging of Quel'Serrar", description = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.\n\nSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.\n\nPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.", sourceObjective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours.", progress = "Perhaps one day, another will wield the prismatic blade.", completion = "<Lydros murmurs something unintelligible.>\n\nAs promised, {class}, the blade of Quel'Serrar.", sourceObjectiveStatus = "unverified-source-field" }
quests[84560] = { id = 84560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Celebrating Good Times", description = "Seek out Major Mattingly in the Valley of Heroes, {name}. He will be expecting you...", sourceObjective = "Seek out Major Mattingly in the Valley of Heroes.", completion = "Few are graced with such ceremony, {name}. Please, choose your reward so that we may begin the celebration.", sourceObjectiveStatus = "unverified-source-field" }
quests[84561] = { id = 84561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For All To See", description = "Overlord Runthak awaits your arrival in the Valley of Strength.\n\n<Thrall salutes you.>\n\nDo not keep your public waiting, hero.", sourceObjective = "Seek out Overlord Runthak in the Valley of Strength.", completion = "Choose your reward and let the celebration of your glorious victory begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[84590] = { id = 84590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Balance of Light and Shadow", description = "You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.\n\nThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.\n\nEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, {name}.", sourceObjective = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain.", completion = "Your tenacity and courage are astounding, {class}. You have earned the right to hold the Splinter of Nordrassil. Only one task remains: The Eye of Shadow must be recovered. Scour the world.", sourceObjectiveStatus = "unverified-source-field" }
quests[84636] = { id = 84636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prowler", description = "Da druids be concerned about a fragment of earth in da barrows east of da lake. It be guarded by angry earth elementals, and preventing da druids from carrying out dere rites.\n\nDescend into da barrows and retrieve the elemental fragment. Take my cat companion, Siopi, to sneak past da elementals, if you do not have a cat companion of your own. Siopi probably be asleep in da grass near here.", sourceObjective = "Travel to the barrows on the east side of Moonglade, on Kalimdor. Descend into the southeastern most Stormrage barrow den, and look for an earth elemental fragment in the depths. Use the Prowl skill of an animal companion to bypass the guardians and retrieve a fragment of elemental earth.", progress = "Have you taken da earth fragment from da barrows?", completion = "Ah, da earth shard. Da druids will take dis with da air shard and return dem where dey need to go.", sourceObjectiveStatus = "unverified-source-field" }
quests[84777] = { id = 84777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathers for Nafien", progress = "While you have proven yourself to me, you may need to continue to work toward proving yourself to the suspicious brethren of my tribe.  To that end, I may be able to continue assisting you.\n\nSome of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers.  Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Well done, {name}!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the feathers you find to me.  I will continue to accept them as long as necessary." }
quests[84853] = { id = 84853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracks in the Snow", description = "You done a good service, so now I help you. Last time I saw Van Amburgh, he had a menagerie of three animals: a great cat, a raptor, and a monstrous bug. He keep dem in cages, whip dem, drive dem to be mean. Cruelty and hunger be his training tools. Fought him in Feralas a while ago, not sure where he be now.\n\nYou should go meet up with Estelenn and see if she be needing ya. And be sure to give her my regards.", sourceObjective = "Travel to the hills in Winterspring in northern Kalimdor, north of Everlook, to meet up with Estelenn and find out what else she needs.", completion = "The remains of Estelenn's old campsite are cold. You may have to wait a while for her to come back. Better get comfortable.", sourceObjectiveStatus = "unverified-source-field" }
quests[84870] = { id = 84870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Hoard", description = "The document is a report from one of Razorgore's underlings. There are rumors that some Blackrock orcs are hiding illicit magical artifacts in the storehouse. It is unclear whether this a simple smuggling operation, or something deeper.\n\nEither way, it sounds like a lucrative score. Best go alone to avoid detection. No need to split the loot either.", sourceObjective = "Break into the storeroom of Blackrock Spire, and steal whatever valuables are inside. You must complete the job alone.", completion = "I can see now that you're not one of them. My apologies.", sourceObjectiveStatus = "unverified-source-field" }
quests[84880] = { id = 84880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy of my Enemy", description = "I was sent here, along with a mage, to steal the Blade of Devouring for the Syndicate. As soon as I picked the locks, however, he attacked me. He took the blade for himself, and left me for dead. \n\nThe mage's name was Caius. He joined us not long ago; promising to share his knowledge of a powerful ritual in exchange for help with stealing its final reagent.\n\nThat traitorous snake, and his ritual, must be stopped. He can't get away with this!", sourceObjective = "A terrible threat is brewing within the Syndicate. Someone at Ravenholdt might know what to do.", completion = "I see why you've brought this to me, {class}. Troubling news indeed. We must consider our next move carefully. Leave me for a moment, so that I can think.", sourceObjectiveStatus = "unverified-source-field" }
quests[84881] = { id = 84881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Hold of Shadows", description = "Caius' betrayal is a troubling wrinkle. It points towards another, more dangerous, organization.\n\nOur intelligence indicates that this may be the Shadow Council.\n  \nThe council's base of operations is Shadow Hold, in Felwood. If our information is correct, Caius' ritual will likely be performed there. You must infiltrate Shadow Hold, find Caius, and stop him.\n\nIt is imperative you remain undetected. If Caius catches wind of your presence, he is likely flee, or have you killed.", sourceObjective = "Find Caius inside of Shadow Hold, in Felwood, and stop his ritual. In addition, bring proof of his demise to Fahrad at Ravenholdt Manor. You must go alone, and remain unseen until you find Caius.", progress = "Have you found Caius yet?", completion = "So Caius was indeed an ally of the Shadow Council. The implications of such a conspiracy could be massive.\n\nYour mission's success has provided valuable intelligence, and thwarted a great danger to all of Azeroth. Excellent work, {name}.   \n\nAs for this \"Dream Eater\" you've recovered: I shudder to think what it could have been if Caius had completed his ritual. Wield it with finesse, and choose your targets wisely.", sourceObjectiveStatus = "unverified-source-field" }
quests[84950] = { id = 84950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out in the Cold", description = "The old campsite has a few useful bits of wood and a striking flint. To find more of Estelenn's tracks or wait for her return, you'll need to collect the materials to make your own camp so that you can survive the oncoming snowstorm.\n\nThough you can avoid the storm by heading out of the hills, you'll have to come back to find the clues that you need.", sourceObjective = "Use your survival supplies to set up a campsite foundation and a crude tent.\n\nIf you lose your foundation, make a new one with your survival supplies and bring the materials there.", completion = "A tent will help protect you from the elements, so that you can wait out here a bit longer without freezing to death.", sourceObjectiveStatus = "unverified-source-field" }
quests[85030] = { id = 85030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Tomb", description = "Before we are hasty to make assumptions about the authenticity of that sample, we should verify that is real. It's going to be difficult to tell for sure, but we may be able to gain some insight by taking this sample to Uther's Tomb in the Western Plaguelands. Speak with the Priest there, Thel'danis. He is a diligent scholar on the life of the lightbringer. With any luck, he can divine its authenticity.", sourceObjective = "Take the Blood of the Lightbringer and speak with High Priest Thel'danis there to determine the authenticity of the relic.", sourceObjectiveStatus = "unverified-source-field" }
quests[85034] = { id = 85034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Andorhal", description = "Remains such as the one you carry tend to have mysterious properties. Some particularly powerful relics may even seem sentient or have a personality at times, particularly in proximity to individuals and places closely tied to their living selves. \n\nIf this truly is Uther's blood, there is a chance it may react when near to the place Uther died. Explore the town and see what happens.", sourceObjective = "Take the Blood of the Lightbringer and explore Andorhal.", progress = "Have you explored Andorhal yet? Did the blood react in any way?", completion = "So there is no doubt then, the blood is authentic. What you have there is a treasure, {class}. Take care and protect it with your life.", sourceObjectiveStatus = "unverified-source-field" }
quests[85061] = { id = 85061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bug Hunt", description = "I followed your tracks and I'm glad to see you're alive! It seems that your survival skills are as good as I suspected. I apologize for keeping you waiting.\n\nI found more signs of our quarry. Van Amburgh is somewhere in the southwest of Kalimdor. I'm going to head that way and keep looking for tracks. In the meantime, you may want to brush up on your shooting.\n\nHead to Silithus. You can aid the druids at the Cenarion Hold while brushing up on your trick shots.", sourceObjective = "Travel to the Cenarion Hold in Silithus, on Kalimdor, and speak to the druids there about the evolving silithids. Aid them as requested while practicing your marksmanship skills.", completion = "Welcome to Cenarion Hold. You look like a capable {class}, and honestly, we can always use some extra help.", sourceObjectiveStatus = "unverified-source-field" }
quests[85063] = { id = 85063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culmination", description = "Once we begin the ritual, I can't be sure what will happen. This place is crawling with demons and if they detect our ritual, we may need to defend ourselves. You and Ada will need to focus on that while I channel the spell. Please stay close however, as you yourself are a vital part of this magic.", sourceObjective = "Defend Gregory as he completes the ritual to destroy the Mannoroc Echoing Orb.", progress = "Be on your guard, {class}.", completion = "No... no. This cannot be! We were so close!  \n\nI have failed my mission. Azgaloth is unleashed. We need to regroup and plan our next steps.", sourceObjectiveStatus = "unverified-source-field" }
quests[85064] = { id = 85064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worst Case Scenario", description = "Time is now against us. The dreadlord mentioned Demon Fall Canyon, so the good news is we know where they are headed. The bad news is that we've likely strengthened Azgaloth's anchor to Azeroth with our failed ritual. Even if we slay Azgaloth now, he would soon manifest himself again.\n\nI have an idea. It's desperate, but it might be our only hope. There's someone in Andorhal with a very particular set of skills that might be able to help, but we'll need to build some trust with her first.", sourceObjective = "Travel to Andorhal and locate Gregory to learn what to do next.", progress = "You made it, good.", completion = "The reliquary of Uther's blood was the key to that ritual, but it was unfortunately lost in the attack. As I said before, this magic is all about building and breaking connections. If we could find another sample of that blood we use could against Azgaloth's physical form and slay him to banish his soul from Azeroth completely.\n\nHow much do you know about bronze dragons?", sourceObjectiveStatus = "unverified-source-field" }
quests[85065] = { id = 85065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Curious Gnome", description = "What we need to finish this mission exists right here in Andorhal, it just isn't here right now. \n\nThe room behind me contains a \"gnome\" named Chromie. She's a rather curious creature who is is known to utilize a very  special type of draconic magic. Time magic, in point of fact.\n\nIf we could convince her to use her magic to help us, we might be able to reach through time briefly and get what we need. It's a gambit, but it just might be our only option. See if you can convince her to lend us her aid.", sourceObjective = "Speak with Chromie in Andorhal and convince her to help you.", completion = "It's great to see you again, {name}! At least I think we've met already. We've met right? It gets hard to keep track of all the different versions of each person I've met... or will meet.", sourceObjectiveStatus = "unverified-source-field" }
quests[85066] = { id = 85066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Ready", description = "Demons invading and death rituals! That all sounds very scary. Luckily this handy little time bubble we are standing in makes connecting ourselves to a specific point in time at this location easy.\n\nThis will be dangerous, though. When you and your friend are ready, say the word.", sourceObjective = "Talk to Gregory in Andorhal and ask him to accompany you to the Burning of Andorhal.", completion = "It's really happening then... \n\nAs much as I hate to admit it, I don't think that I'm the best person to go back with you. My body has suffered too much damage between Aeonas' holy fire and the demon attack. In my current state I'm more likely to slow you down than to help. With Ada dead I think we might need outside aid.", sourceObjectiveStatus = "unverified-source-field" }
